-- Seed subjects (units) + flashcards for Constitución Española (dev)
-- Generated from Constitución Española PDF. Idempotent via ON CONFLICT.
-- ============ FLASHCARDS (merged from R__seed_flashcards.sql) ============
-- NOTE: Using units from this file (R__seed_basic_data.sql). Flashcards reference existing unit ids.
INSERT INTO flashcards(id, unit_id, front, back, created_at, updated_at) VALUES
('01563f10-f05d-57eb-992a-ec31b9a074ca','11111111-1111-1111-1111-111111111202','Artículo 1.1 — ¿Qué establece este apartado?','España se constituye en un Estado social y democrático de
Derecho, que propugna como valores superiores de su
ordenamiento jurídico la libertad, la justicia, la igualdad y el
pluralismo político.', now(), now()),
('91c7f0a7-8576-5358-a7f5-ab23d736148f','11111111-1111-1111-1111-111111111202','Artículo 1.2 — ¿Qué establece este apartado?','La soberanía nacional reside en el pueblo español, del que
emanan los poderes del Estado.', now(), now()),
('0d9a4cda-59b1-516f-afa9-491d3354fefd','11111111-1111-1111-1111-111111111202','Artículo 1.3 — ¿Qué establece este apartado?','La forma política del Estado español es la Monarquía parlamentaria.', now(), now()),
('5a6f7c14-cf86-5238-a0b6-7f8ef370cb95','11111111-1111-1111-1111-111111111202','Artículo 2 — ¿Qué establece?','La Constitución se fundamenta en la indisoluble unidad de la
Nación española, patria común e indivisible de todos los españoles, y reconoce y garantiza el derecho a la autonomía de las
nacionalidades y regiones que la integran y la solidaridad entre
todas ellas.', now(), now()),
('410ea915-6059-5180-9052-ad9aa21bdf11','11111111-1111-1111-1111-111111111202','Artículo 3.1 — ¿Qué establece este apartado?','El castellano es la lengua española oficial del Estado. Todos
los españoles tienen el deber de conocerla y el derecho a
usarla.', now(), now()),
('ff70d1c6-5b73-5d6e-bb5c-bda1776721c4','11111111-1111-1111-1111-111111111202','Artículo 3.2 — ¿Qué establece este apartado?','Las demás lenguas españolas serán también oficiales en las
respectivas Comunidades Autónomas de acuerdo con sus
Estatutos.', now(), now()),
('f09aa8e3-e2d2-5410-bd43-bcb8f50e9181','11111111-1111-1111-1111-111111111202','Artículo 3.3 — ¿Qué establece este apartado?','La riqueza de las distintas modalidades lingüísticas de
España es un patrimonio cultural que será objeto de especial respeto y protección.', now(), now()),
('249788a8-5ffe-5b5b-bd22-fb7484b6ca50','11111111-1111-1111-1111-111111111202','Artículo 4.1 — ¿Qué establece este apartado?','La bandera de España está formada por tres franjas horizontales, roja, amarilla y roja, siendo la amarilla de doble
anchura que cada una de las rojas.', now(), now()),
('bab0e6fe-c2fb-55a3-a273-4e916070715c','11111111-1111-1111-1111-111111111202','Artículo 4.2 — ¿Qué establece este apartado?','Los Estatutos podrán reconocer banderas y enseñas propias
de las Comunidades Autónomas. Estas se utilizarán junto a
la bandera de España en sus edificios públicos y en sus actos
oficiales.', now(), now()),
('46f4dac7-c4a8-54ac-9c95-7ea1cbde8e9f','11111111-1111-1111-1111-111111111202','Artículo 5 — ¿Qué establece?','La capital del Estado es la villa de Madrid.', now(), now()),
('3d08d2d6-5622-56ae-a64b-4ea9af4248c0','11111111-1111-1111-1111-111111111202','Artículo 6 — ¿Qué establece?','Los partidos políticos expresan el pluralismo político, concurren
a la formación y manifestación de la voluntad popular y son instrumento fundamental para la participación política. Su creación
y el ejercicio de su actividad son libres dentro del respeto a la
Constitución y a la ley. Su estructura interna y funcionamiento
deberán ser democráticos.', now(), now()),
('e5a2735b-1c7f-5381-93d4-fdef77dd1fbf','11111111-1111-1111-1111-111111111202','Artículo 7 — ¿Qué establece?','Los sindicatos de trabajadores y las asociaciones empresariales
contribuyen a la defensa y promoción de los intereses económicos y sociales que les son propios. Su creación y el ejercicio de
su actividad son libres dentro del respeto a la Constitución y a
la ley. Su estructura interna y funcionamiento deberán ser democráticos.', now(), now()),
('c6745d74-710a-57fc-a3ba-5adcce862ac8','11111111-1111-1111-1111-111111111202','Artículo 8.1 — ¿Qué establece este apartado?','Las Fuerzas Armadas, constituidas por el Ejército de Tierra,
la Armada y el Ejército del Aire, tienen como misión garantizar la soberanía e independencia de España, defender su
integridad territorial y el ordenamiento constitucional.', now(), now()),
('2e7671d5-73db-5667-b0e9-ead877b3c2de','11111111-1111-1111-1111-111111111202','Artículo 8.2 — ¿Qué establece este apartado?','Una ley orgánica regulará las bases de la organización militar conforme a los principios de la presente Constitución.', now(), now()),
('19c565d2-e197-521b-94ac-74138adedbcd','11111111-1111-1111-1111-111111111202','Artículo 9.1 — ¿Qué establece este apartado?','Los ciudadanos y los poderes públicos están sujetos a la
Constitución y al resto del ordenamiento jurídico.', now(), now()),
('8ad27af6-7443-5983-9bb9-fac2f573a2d1','11111111-1111-1111-1111-111111111202','Artículo 9.2 — ¿Qué establece este apartado?','Corresponde a los poderes públicos promover las condiciones para que la libertad y la igualdad del individuo y de los
grupos en que se integra sean reales y efectivas; remover
los obstáculos que impidan o dificulten su plenitud y facilitar
la participación de todos los ciudadanos en la vida política,
económica, cultural y social.', now(), now()),
('4ff668c5-5884-5810-a1f3-acb40c68b08d','11111111-1111-1111-1111-111111111202','Artículo 9.3 — ¿Qué establece este apartado?','La Constitución garantiza el principio de legalidad, la jerarquía normativa, la publicidad de las normas, la irretroactividad de las disposiciones sancionadoras no favorables o
restrictivas de derechos individuales, la seguridad jurídica,
la responsabilidad y la interdicción de la arbitrariedad de los
poderes públicos.
TÍTULO I
De los derechos y deberes fundamentales', now(), now()),
('d512bf03-ea75-5e85-a834-97970d313632','11111111-1111-1111-1111-111111111203','Artículo 10.1 — ¿Qué establece este apartado?','La dignidad de la persona, los derechos inviolables que le
son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás son fundamento
del orden político y de la paz social.', now(), now()),
('d0a93cb2-092f-529b-9f90-5a04a577639c','11111111-1111-1111-1111-111111111203','Artículo 10.2 — ¿Qué establece este apartado?','Las normas relativas a los derechos fundamentales y a las
libertades que la Constitución reconoce se interpretarán de
conformidad con la Declaración Universal de Derechos
Humanos y los tratados y acuerdos internacionales sobre las
mismas materias ratificados por España.
CAPÍTULO PRIMERO
de los españoles y los extRanjeRos', now(), now()),
('24265e2b-ea2d-53a3-8cb1-7eef052c3be6','11111111-1111-1111-1111-111111111203','Artículo 11.1 — ¿Qué establece este apartado?','La nacionalidad española se adquiere, se conserva y se
pierde de acuerdo con lo establecido por la ley.', now(), now()),
('d1511cbd-f44b-5a72-999e-8cbd3a15e203','11111111-1111-1111-1111-111111111203','Artículo 11.2 — ¿Qué establece este apartado?','Ningún español de origen podrá ser privado de su nacionalidad.', now(), now()),
('1ffc5bfd-2e76-57b6-a584-6068243981d2','11111111-1111-1111-1111-111111111203','Artículo 11.3 — ¿Qué establece este apartado?','El Estado podrá concertar tratados de doble nacionalidad
con los países iberoamericanos o con aquellos que hayan
tenido o tengan una particular vinculación con España. En
estos mismos países, aun cuando no reconozcan a sus ciudadanos un derecho recíproco, podrán naturalizarse los
españoles sin perder su nacionalidad de origen.', now(), now()),
('f27bca09-45e7-5a73-a814-3ee6fade57e0','11111111-1111-1111-1111-111111111203','Artículo 12 — ¿Qué establece?','Los españoles son mayores de edad a los dieciocho años.', now(), now()),
('3f663fca-a602-5878-ba77-aa609e39a6fa','11111111-1111-1111-1111-111111111203','Artículo 13.1 — ¿Qué establece este apartado?','Los extranjeros gozarán en España de las libertades públicas
que garantiza el presente Título en los términos que establezcan los tratados y la ley.', now(), now()),
('80101242-9a83-506d-97e3-c17ac1227c68','11111111-1111-1111-1111-111111111203','Artículo 13.2 — ¿Qué establece este apartado?','Solamente los españoles serán titulares de los derechos
reconocidos en el artículo 23, salvo lo que, atendiendo a
criterios de reciprocidad, pueda establecerse por tratado o
ley para el derecho de sufragio activo y pasivo en las elecciones municipales.', now(), now()),
('1261ef42-5e81-50ce-8a3c-531163b7b896','11111111-1111-1111-1111-111111111203','Artículo 13.3 — ¿Qué establece este apartado?','La extradición sólo se concederá en cumplimiento de un
tratado o de la ley, atendiendo al principio de reciprocidad.
Quedan excluidos de la extradición los delitos políticos, no
considerándose como tales los actos de terrorismo.', now(), now()),
('1d4dc39c-4590-53df-8ade-2a835b4fcc79','11111111-1111-1111-1111-111111111203','Artículo 13.4 — ¿Qué establece este apartado?','La ley establecerá los términos en que los ciudadanos de
otros países y los apátridas podrán gozar del derecho de
asilo en España.
CAPÍTULO SEGUNDO
deRechos y libeRtades', now(), now()),
('1a95d0c4-44de-56f4-b138-40e30f572192','11111111-1111-1111-1111-111111111204','Artículo 14 — ¿Qué establece?','Los españoles son iguales ante la ley, sin que pueda prevalecer
discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal
o social.
Sección 1.ª De los derechos fundamentales y de las libertades
públicas', now(), now()),
('9cd1063c-3390-511b-ad7a-c5821490f9e2','11111111-1111-1111-1111-111111111204','Artículo 15 — ¿Qué establece?','Todos tienen derecho a la vida y a la integridad física y moral,
sin que, en ningún caso, puedan ser sometidos a tortura ni a
penas o tratos inhumanos o degradantes. Queda abolida la
pena de muerte, salvo lo que puedan disponer las leyes penales
militares para tiempos de guerra.', now(), now()),
('9f91d505-9440-54de-8a08-0325dd507f99','11111111-1111-1111-1111-111111111204','Artículo 16.1 — ¿Qué establece este apartado?','Se garantiza la libertad ideológica, religiosa y de culto de los
individuos y las comunidades sin más limitación, en sus
manifestaciones, que la necesaria para el mantenimiento del
orden público protegido por la ley.', now(), now()),
('e03ff77e-1bcc-52b4-85e3-42e593722dbd','11111111-1111-1111-1111-111111111204','Artículo 16.2 — ¿Qué establece este apartado?','Nadie podrá ser obligado a declarar sobre su ideología, religión o creencias.', now(), now()),
('f34347a9-a6ab-5fa3-82b8-366ea15dc096','11111111-1111-1111-1111-111111111204','Artículo 16.3 — ¿Qué establece este apartado?','Ninguna confesión tendrá carácter estatal. Los poderes
públicos tendrán en cuenta las creencias religiosas de la
sociedad española y mantendrán las consiguientes relaciones de cooperación con la Iglesia Católica y las demás confesiones.', now(), now()),
('bed000d3-493a-5867-8738-05a3613884d2','11111111-1111-1111-1111-111111111204','Artículo 17.1 — ¿Qué establece este apartado?','Toda persona tiene derecho a la libertad y a la seguridad.
Nadie puede ser privado de su libertad, sino con la observancia de lo establecido en este artículo y en los casos y en
la forma previstos en la ley.', now(), now()),
('60b1946c-c0d8-5c50-ae40-bfdac120a6c4','11111111-1111-1111-1111-111111111204','Artículo 17.2 — ¿Qué establece este apartado?','La detención preventiva no podrá durar más del tiempo
estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos, y, en
todo caso, en el plazo máximo de setenta y dos horas, el
detenido deberá ser puesto en libertad o a disposición de
la autoridad judicial.', now(), now()),
('217e9a4f-86db-5faf-9f01-85bb53514d46','11111111-1111-1111-1111-111111111204','Artículo 17.3 — ¿Qué establece este apartado?','Toda persona detenida debe ser informada de forma inmediata, y de modo que le sea comprensible, de sus derechos
y de las razones de su detención, no pudiendo ser obligada
a declarar. Se garantiza la asistencia de abogado al detenido en las diligencias policiales y judiciales, en los términos
que la ley establezca.', now(), now()),
('fd3dffe2-b78a-5648-a0bd-44e2f9258ab7','11111111-1111-1111-1111-111111111204','Artículo 17.4 — ¿Qué establece este apartado?','La ley regulará un procedimiento de «habeas corpus» para
producir la inmediata puesta a disposición judicial de toda
persona detenida ilegalmente. Asimismo, por ley se determinará el plazo máximo de duración de la prisión provisional.', now(), now()),
('357575f3-545b-521c-b7ba-38ce32641d87','11111111-1111-1111-1111-111111111204','Artículo 18.1 — ¿Qué establece este apartado?','Se garantiza el derecho al honor, a la intimidad personal y
familiar y a la propia imagen.', now(), now()),
('523b46c1-2c6c-5afc-aa38-a8a65c4661e6','11111111-1111-1111-1111-111111111204','Artículo 18.2 — ¿Qué establece este apartado?','El domicilio es inviolable. Ninguna entrada o registro podrá
hacerse en él sin consentimiento del titular o resolución judicial, salvo en caso de flagrante delito.', now(), now()),
('f1fe085d-b704-5413-9829-7ce081204a1c','11111111-1111-1111-1111-111111111204','Artículo 18.3 — ¿Qué establece este apartado?','Se garantiza el secreto de las comunicaciones y, en especial,
de las postales, telegráficas y telefónicas, salvo resolución
judicial.', now(), now()),
('80cde955-4712-5347-8ce9-59bfbc2e053a','11111111-1111-1111-1111-111111111204','Artículo 18.4 — ¿Qué establece este apartado?','La ley limitará el uso de la informática para garantizar el
honor y la intimidad personal y familiar de los ciudadanos y
el pleno ejercicio de sus derechos.', now(), now()),
('89b6ce6a-9f39-500c-8dd3-6a09493297b1','11111111-1111-1111-1111-111111111204','Artículo 19 — ¿Qué establece?','Los españoles tienen derecho a elegir libremente su residencia
y a circular por el territorio nacional.
Asimismo, tienen derecho a entrar y salir libremente de España
en los términos que la ley establezca. Este derecho no podrá ser
limitado por motivos políticos o ideológicos.', now(), now()),
('161c7fdb-d1ad-5202-9c16-67f427e1a079','11111111-1111-1111-1111-111111111204','Artículo 20.1 — ¿Qué establece este apartado?','Se reconocen y protegen los derechos:
a) A expresar y difundir libremente los pensamientos,
ideas y opiniones mediante la palabra, el escrito o cualquier otro medio de reproducción.
b) A la producción y creación literaria, artística, científica y
técnica.
c) A la libertad de cátedra.
d) A comunicar o recibir libremente información veraz por
cualquier medio de difusión. La ley regulará el derecho
a la cláusula de conciencia y al secreto profesional en el
ejercicio de estas libertades.', now(), now()),
('fb6d206a-7264-580e-a879-4487bf2d0286','11111111-1111-1111-1111-111111111204','Artículo 20.2 — ¿Qué establece este apartado?','El ejercicio de estos derechos no puede restringirse
mediante ningún tipo de censura previa.', now(), now()),
('2ab3176d-e417-5939-a2c9-51e6f9019470','11111111-1111-1111-1111-111111111204','Artículo 20.3 — ¿Qué establece este apartado?','La ley regulará la organización y el control parlamentario de
los medios de comunicación social dependientes del Estado
o de cualquier ente público y garantizará el acceso a dichos
medios de los grupos sociales y políticos significativos, respetando el pluralismo de la sociedad y de las diversas lenguas de España.', now(), now()),
('eb18e942-1b4f-57b9-b721-b99f690a10b8','11111111-1111-1111-1111-111111111204','Artículo 20.4 — ¿Qué establece este apartado?','Estas libertades tienen su límite en el respeto a los derechos
reconocidos en este Título, en los preceptos de las leyes
que lo desarrollen y, especialmente, en el derecho al honor,
a la intimidad, a la propia imagen y a la protección de la
juventud y de la infancia.', now(), now()),
('a7b37f43-2493-5733-ba54-44813f1b7843','11111111-1111-1111-1111-111111111204','Artículo 20.5 — ¿Qué establece este apartado?','Sólo podrá acordarse el secuestro de publicaciones, grabaciones y otros medios de información en virtud de resolución judicial.', now(), now()),
('70d8b813-d1b5-58a2-9113-4ff5f13d4a39','11111111-1111-1111-1111-111111111204','Artículo 21.1 — ¿Qué establece este apartado?','Se reconoce el derecho de reunión pacífica y sin armas. El
ejercicio de este derecho no necesitará autorización previa.', now(), now()),
('709dc117-0caf-5ea7-9233-413711936133','11111111-1111-1111-1111-111111111204','Artículo 21.2 — ¿Qué establece este apartado?','En los casos de reuniones en lugares de tránsito público y
manifestaciones se dará comunicación previa a la autoridad,
que sólo podrá prohibirlas cuando existan razones fundadas
de alteración del orden público, con peligro para personas
o bienes.', now(), now()),
('2be6260d-9d9f-5240-a8be-6a17844cfcfa','11111111-1111-1111-1111-111111111204','Artículo 22.1 — ¿Qué establece este apartado?','Se reconoce el derecho de asociación.', now(), now()),
('09a4b04d-7174-5195-8b24-808321ce360b','11111111-1111-1111-1111-111111111204','Artículo 22.2 — ¿Qué establece este apartado?','Las asociaciones que persigan fines o utilicen medios tipificados como delito son ilegales.', now(), now()),
('b394bb09-b4e8-51cb-8aad-03572a3a2b58','11111111-1111-1111-1111-111111111204','Artículo 22.3 — ¿Qué establece este apartado?','Las asociaciones constituidas al amparo de este artículo
deberán inscribirse en un registro a los solos efectos de
publicidad.', now(), now()),
('2de42836-cf97-5e7a-b047-f6cc56a9b40c','11111111-1111-1111-1111-111111111204','Artículo 22.4 — ¿Qué establece este apartado?','Las asociaciones sólo podrán ser disueltas o suspendidas en
sus actividades en virtud de resolución judicial motivada.', now(), now()),
('6eb5aacb-b122-5d27-b8c0-d2f48be6abce','11111111-1111-1111-1111-111111111204','Artículo 22.5 — ¿Qué establece este apartado?','Se prohíben las asociaciones secretas y las de carácter paramilitar.', now(), now()),
('f8aaec46-f3e6-59be-9502-990fe9ff6c1d','11111111-1111-1111-1111-111111111204','Artículo 23.1 — ¿Qué establece este apartado?','Los ciudadanos tienen el derecho a participar en los asuntos
públicos, directamente o por medio de representantes,
libremente elegidos en elecciones periódicas por sufragio
universal.', now(), now()),
('6d8bc5f6-9a6c-574b-8274-72af6bf08770','11111111-1111-1111-1111-111111111204','Artículo 23.2 — ¿Qué establece este apartado?','Asimismo, tienen derecho a acceder en condiciones de
igualdad a las funciones y cargos públicos, con los requisitos
que señalen las leyes.', now(), now()),
('87fb1e1c-e695-5f1a-83a1-a96f58b8835f','11111111-1111-1111-1111-111111111204','Artículo 24.1 — ¿Qué establece este apartado?','Todas las personas tienen derecho a obtener la tutela efectiva de los jueces y tribunales en el ejercicio de sus derechos
e intereses legítimos, sin que, en ningún caso, pueda producirse indefensión.', now(), now()),
('08580bdc-7814-5cb8-ac22-1429ae49f017','11111111-1111-1111-1111-111111111204','Artículo 24.2 — ¿Qué establece este apartado?','Asimismo, todos tienen derecho al Juez ordinario predeterminado por la ley, a la defensa y a la asistencia de letrado, a
ser informados de la acusación formulada contra ellos, a un
proceso público sin dilaciones indebidas y con todas las
garantías, a utilizar los medios de prueba pertinentes para
su defensa, a no declarar contra sí mismos, a no confesarse
culpables y a la presunción de inocencia.
La ley regulará los casos en que, por razón de parentesco o
de secreto profesional, no se estará obligado a declarar
sobre hechos presuntamente delictivos.', now(), now()),
('7666c060-9657-57ac-a5b1-20695a040462','11111111-1111-1111-1111-111111111204','Artículo 25.1 — ¿Qué establece este apartado?','Nadie puede ser condenado o sancionado por acciones u
omisiones que en el momento de producirse no constituyan
delito, falta o infracción administrativa, según la legislación
vigente en aquel momento.', now(), now()),
('a71e80e3-f0f6-51c1-a66d-1f160855dd10','11111111-1111-1111-1111-111111111204','Artículo 25.2 — ¿Qué establece este apartado?','Las penas privativas de libertad y las medidas de seguridad
estarán orientadas hacia la reeducación y reinserción social
y no podrán consistir en trabajos forzados. El condenado a
pena de prisión que estuviere cumpliendo la misma gozará
de los derechos fundamentales de este Capítulo, a excepción de los que se vean expresamente limitados por el contenido del fallo condenatorio, el sentido de la pena y la ley
penitenciaria. En todo caso, tendrá derecho a un trabajo
remunerado y a los beneficios correspondientes de la Seguridad Social, así como al acceso a la cultura y al desarrollo
integral de su personalidad.', now(), now()),
('465a2c0d-e191-5c8b-b624-d3a30c12fae9','11111111-1111-1111-1111-111111111204','Artículo 25.3 — ¿Qué establece este apartado?','La Administración civil no podrá imponer sanciones que,
directa o subsidiariamente, impliquen privación de libertad.', now(), now()),
('d63b842d-78da-5fd1-a143-c79bd310f17d','11111111-1111-1111-1111-111111111204','Artículo 26 — ¿Qué establece?','Se prohíben los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales.', now(), now()),
('6024fb7c-7f0a-583c-b7cb-a6a7a71a494f','11111111-1111-1111-1111-111111111204','Artículo 27.1 — ¿Qué establece este apartado?','Todos tienen el derecho a la educación. Se reconoce la
libertad de enseñanza.', now(), now()),
('fc97674a-1540-5af1-84ed-dd170d28c635','11111111-1111-1111-1111-111111111204','Artículo 27.2 — ¿Qué establece este apartado?','La educación tendrá por objeto el pleno desarrollo de la personalidad humana en el respeto a los principios democráticos
de convivencia y a los derechos y libertades fundamentales.', now(), now()),
('b2f3c5f2-678a-5856-92ac-f86e9e5f22d5','11111111-1111-1111-1111-111111111204','Artículo 27.3 — ¿Qué establece este apartado?','Los poderes públicos garantizan el derecho que asiste a los
padres para que sus hijos reciban la formación religiosa y
moral que esté de acuerdo con sus propias convicciones.', now(), now()),
('68a5853c-0364-5963-8b1f-febf8b921c15','11111111-1111-1111-1111-111111111204','Artículo 27.4 — ¿Qué establece este apartado?','La enseñanza básica es obligatoria y gratuita.', now(), now()),
('fb6c8510-6065-550b-b3dd-67818bb1417b','11111111-1111-1111-1111-111111111204','Artículo 27.5 — ¿Qué establece este apartado?','Los poderes públicos garantizan el derecho de todos a la
educación, mediante una programación general de la enseñanza, con participación efectiva de todos los sectores afectados y la creación de centros docentes.', now(), now()),
('c7d95206-befa-5461-85a4-0395d4191452','11111111-1111-1111-1111-111111111204','Artículo 27.6 — ¿Qué establece este apartado?','Se reconoce a las personas físicas y jurídicas la libertad de
creación de centros docentes, dentro del respeto a los principios constitucionales.', now(), now()),
('a6d2d670-b204-5437-bb54-c260495856dd','11111111-1111-1111-1111-111111111204','Artículo 27.7 — ¿Qué establece este apartado?','Los profesores, los padres y, en su caso, los alumnos intervendrán en el control y gestión de todos los centros sostenidos por la Administración con fondos públicos, en los
términos que la ley establezca.', now(), now()),
('ec19e007-b956-5160-94e7-b5954e48417b','11111111-1111-1111-1111-111111111204','Artículo 27.8 — ¿Qué establece este apartado?','Los poderes públicos inspeccionarán y homologarán el sistema educativo para garantizar el cumplimiento de las leyes.', now(), now()),
('83d9bbcd-5ff9-56ba-bf76-0affcf0139f9','11111111-1111-1111-1111-111111111204','Artículo 27.9 — ¿Qué establece este apartado?','Los poderes públicos ayudarán a los centros docentes que
reúnan los requisitos que la ley establezca.', now(), now()),
('055cb636-3928-5feb-92dd-7b62b04ebbd6','11111111-1111-1111-1111-111111111204','Artículo 27.10 — ¿Qué establece este apartado?','Se reconoce la autonomía de las Universidades, en los términos que la ley establezca.', now(), now()),
('5367ad01-3857-5462-a248-848e99eb4c04','11111111-1111-1111-1111-111111111204','Artículo 28.1 — ¿Qué establece este apartado?','Todos tienen derecho a sindicarse libremente. La ley podrá
limitar o exceptuar el ejercicio de este derecho a las Fuerzas
o Institutos armados o a los demás Cuerpos sometidos a
disciplina militar y regulará las peculiaridades de su ejercicio
para los funcionarios públicos. La libertad sindical comprende el derecho a fundar sindicatos y a afiliarse al de su
elección, así como el derecho de los sindicatos a formar
confederaciones y a fundar organizaciones sindicales internacionales o a afiliarse a las mismas. Nadie podrá ser obligado a afiliarse a un sindicato.', now(), now()),
('a88a9a29-893c-553a-98c4-7dcc4dcce3cf','11111111-1111-1111-1111-111111111204','Artículo 28.2 — ¿Qué establece este apartado?','Se reconoce el derecho a la huelga de los trabajadores para
la defensa de sus intereses. La ley que regule el ejercicio de
este derecho establecerá las garantías precisas para asegurar
el mantenimiento de los servicios esenciales de la comunidad.', now(), now()),
('9aa2ffd6-95f0-5309-a9d3-74eef9ee66b3','11111111-1111-1111-1111-111111111204','Artículo 29.1 — ¿Qué establece este apartado?','Todos los españoles tendrán el derecho de petición individual y colectiva, por escrito, en la forma y con los efectos
que determine la ley.', now(), now()),
('4b867493-4537-562b-a8fd-11c16eaf9356','11111111-1111-1111-1111-111111111204','Artículo 29.2 — ¿Qué establece este apartado?','Los miembros de las Fuerzas o Institutos armados o de los
Cuerpos sometidos a disciplina militar podrán ejercer este
derecho sólo individualmente y con arreglo a lo dispuesto
en su legislación específica.
Sección 2.ª De los derechos y deberes de los ciudadanos', now(), now()),
('d7c756ae-b9fc-531c-b0cd-9a04cea07035','11111111-1111-1111-1111-111111111205','Artículo 30.1 — ¿Qué establece este apartado?','Los españoles tienen el derecho y el deber de defender a
España.', now(), now()),
('0a0de217-4045-5af6-a20d-5000ff9cf5b7','11111111-1111-1111-1111-111111111205','Artículo 30.2 — ¿Qué establece este apartado?','La ley fijará las obligaciones militares de los españoles y
regulará, con las debidas garantías, la objeción de conciencia, así como las demás causas de exención del servicio militar obligatorio, pudiendo imponer, en su caso, una
prestación social sustitutoria.', now(), now()),
('32772146-5d55-5d9c-9d01-828b2556776b','11111111-1111-1111-1111-111111111205','Artículo 30.3 — ¿Qué establece este apartado?','Podrá establecerse un servicio civil para el cumplimiento de
fines de interés general.', now(), now()),
('54bd1630-d53b-5a55-8f27-0ee7fe8e1f07','11111111-1111-1111-1111-111111111205','Artículo 30.4 — ¿Qué establece este apartado?','Mediante ley podrán regularse los deberes de los ciudadanos en los casos de grave riesgo, catástrofe o calamidad
pública.', now(), now()),
('abb17383-9177-5946-b92d-c56c95760b01','11111111-1111-1111-1111-111111111205','Artículo 31.1 — ¿Qué establece este apartado?','Todos contribuirán al sostenimiento de los gastos públicos
de acuerdo con su capacidad económica mediante un sistema tributario justo inspirado en los principios de igualdad
y progresividad que, en ningún caso, tendrá alcance confiscatorio.', now(), now()),
('047f6986-04c4-5f4a-bd87-f549a90bfcd7','11111111-1111-1111-1111-111111111205','Artículo 31.2 — ¿Qué establece este apartado?','El gasto público realizará una asignación equitativa de los
recursos públicos, y su programación y ejecución responderán a los criterios de eficiencia y economía.', now(), now()),
('e1305066-8a25-5cdf-8554-11b87e89cacf','11111111-1111-1111-1111-111111111205','Artículo 31.3 — ¿Qué establece este apartado?','Sólo podrán establecerse prestaciones personales o patrimoniales de carácter público con arreglo a la ley.', now(), now()),
('59df3502-de8f-573c-be0f-11fd1e41240f','11111111-1111-1111-1111-111111111205','Artículo 32.1 — ¿Qué establece este apartado?','El hombre y la mujer tienen derecho a contraer matrimonio
con plena igualdad jurídica.', now(), now()),
('870d1f81-2acf-55cd-bf54-da591c844b1f','11111111-1111-1111-1111-111111111205','Artículo 32.2 — ¿Qué establece este apartado?','La ley regulará las formas de matrimonio, la edad y capacidad para contraerlo, los derechos y deberes de los cónyuges, las causas de separación y disolución y sus efectos.', now(), now()),
('fe0e4375-2b82-5c85-95e9-b37c80dfe82c','11111111-1111-1111-1111-111111111205','Artículo 33.1 — ¿Qué establece este apartado?','Se reconoce el derecho a la propiedad privada y a la herencia.', now(), now()),
('0a3f73d4-4da2-5e9f-a7b1-237d340a0545','11111111-1111-1111-1111-111111111205','Artículo 33.2 — ¿Qué establece este apartado?','La función social de estos derechos delimitará su contenido,
de acuerdo con las leyes.', now(), now()),
('41bff265-e4ca-5b07-9105-bceb8d631cc6','11111111-1111-1111-1111-111111111205','Artículo 33.3 — ¿Qué establece este apartado?','Nadie podrá ser privado de sus bienes y derechos sino por
causa justificada de utilidad pública o interés social,
mediante la correspondiente indemnización y de conformidad con lo dispuesto por las leyes.', now(), now()),
('9ebad33e-8626-5337-883d-85f92cb5c88a','11111111-1111-1111-1111-111111111205','Artículo 34.1 — ¿Qué establece este apartado?','Se reconoce el derecho de fundación para fines de interés
general, con arreglo a la ley.', now(), now()),
('de47533e-f910-532d-82b8-ef4b1c750e8e','11111111-1111-1111-1111-111111111205','Artículo 34.2 — ¿Qué establece este apartado?','Regirá también para las fundaciones lo dispuesto en los
apartados 2 y 4 del artículo 22.', now(), now()),
('53fe1ab0-e76f-53db-87eb-9e308623aec8','11111111-1111-1111-1111-111111111205','Artículo 35.1 — ¿Qué establece este apartado?','Todos los españoles tienen el deber de trabajar y el derecho
al trabajo, a la libre elección de profesión u oficio, a la promoción a través del trabajo y a una remuneración suficiente
para satisfacer sus necesidades y las de su familia, sin que
en ningún caso pueda hacerse discriminación por razón de
sexo.', now(), now()),
('db7f6853-f98e-5c30-b163-f14e2221aa34','11111111-1111-1111-1111-111111111205','Artículo 35.2 — ¿Qué establece este apartado?','La ley regulará un estatuto de los trabajadores.', now(), now()),
('e35d710f-5dab-593e-9623-f0d0dc268080','11111111-1111-1111-1111-111111111205','Artículo 36 — ¿Qué establece?','La ley regulará las peculiaridades propias del régimen jurídico
de los Colegios Profesionales y el ejercicio de las profesiones
tituladas. La estructura interna y el funcionamiento de los Colegios deberán ser democráticos.', now(), now()),
('55357655-6de2-5b74-825d-be17e4534a26','11111111-1111-1111-1111-111111111205','Artículo 37.1 — ¿Qué establece este apartado?','La ley garantizará el derecho a la negociación colectiva laboral entre los representantes de los trabajadores y empresarios, así como la fuerza vinculante de los convenios.', now(), now()),
('2d0186bd-b904-5071-926e-233bf9a9f022','11111111-1111-1111-1111-111111111205','Artículo 37.2 — ¿Qué establece este apartado?','Se reconoce el derecho de los trabajadores y empresarios a
adoptar medidas de conflicto colectivo. La ley que regule el
ejercicio de este derecho, sin perjuicio de las limitaciones que
puedan establecer, incluirá las garantías precisas para asegurar
el funcionamiento de los servicios esenciales de la comunidad.', now(), now()),
('ae287817-1c10-5fae-a6d8-8ad52c9f24dc','11111111-1111-1111-1111-111111111205','Artículo 38 — ¿Qué establece?','Se reconoce la libertad de empresa en el marco de la economía
de mercado. Los poderes públicos garantizan y protegen su ejercicio y la defensa de la productividad, de acuerdo con las exigencias de la economía general y, en su caso, de la planificación.
CAPÍTULO TERCERO
de los pRincipios RectoRes de la política social y económica', now(), now()),
('9436b50d-324b-5f08-8e82-6e61eaf2a2ab','11111111-1111-1111-1111-111111111206','Artículo 39.1 — ¿Qué establece este apartado?','Los poderes públicos aseguran la protección social, económica y jurídica de la familia.', now(), now()),
('dcdddeb0-ff2a-5eda-8bf8-759551eca560','11111111-1111-1111-1111-111111111206','Artículo 39.2 — ¿Qué establece este apartado?','L os poderes públicos aseguran, asimismo, la protección integral de los hijos, iguales éstos ante la ley con independencia
de su filiación, y de las madres, cualquiera que sea su estado
civil. La ley posibilitará la investigación de la paternidad.', now(), now()),
('c0c120c7-8047-50d5-b65f-23575e42454b','11111111-1111-1111-1111-111111111206','Artículo 39.3 — ¿Qué establece este apartado?','Los padres deben prestar asistencia de todo orden a los
hijos habidos dentro o fuera del matrimonio, durante su
minoría de edad y en los demás casos en que legalmente
proceda.', now(), now()),
('a90829ba-de10-5a8c-9859-2ac9b1da2545','11111111-1111-1111-1111-111111111206','Artículo 39.4 — ¿Qué establece este apartado?','Los niños gozarán de la protección prevista en los acuerdos
internacionales que velan por sus derechos.', now(), now()),
('ca0e63fb-d652-5a82-8423-4fb998882164','11111111-1111-1111-1111-111111111206','Artículo 40.1 — ¿Qué establece este apartado?','Los poderes públicos promoverán las condiciones favorables para el progreso social y económico y para una distribución de la renta regional y personal más equitativa, en el
marco de una política de estabilidad económica. De manera
especial realizarán una política orientada al pleno empleo.', now(), now()),
('7a5165f0-6afb-50d2-9f65-fc6ea4843c9f','11111111-1111-1111-1111-111111111206','Artículo 40.2 — ¿Qué establece este apartado?','Asimismo, los poderes públicos fomentarán una política que
garantice la formación y readaptación profesionales; velarán
por la seguridad e higiene en el trabajo y garantizarán el
descanso necesario, mediante la limitación de la jornada
laboral, las vacaciones periódicas retribuidas y la promoción
de centros adecuados.', now(), now()),
('1f535d2b-36eb-5cbe-990f-38947a4ff467','11111111-1111-1111-1111-111111111206','Artículo 41 — ¿Qué establece?','Los poderes públicos mantendrán un régimen público de Seguridad Social para todos los ciudadanos, que garantice la asistencia y prestaciones sociales suficientes ante situaciones de
necesidad, especialmente en caso de desempleo. La asistencia
y prestaciones complementarias serán libres.', now(), now()),
('c47b3a4f-f6e5-513d-bd14-b7c3c4863ce4','11111111-1111-1111-1111-111111111207','Artículo 42 — ¿Qué establece?','El Estado velará especialmente por la salvaguardia de los derechos económicos y sociales de los trabajadores españoles en el
extranjero y orientará su política hacia su retorno.', now(), now()),
('f8bb8355-d7aa-58fa-9737-5526ef0e7002','11111111-1111-1111-1111-111111111207','Artículo 43.1 — ¿Qué establece este apartado?','Se reconoce el derecho a la protección de la salud.', now(), now()),
('d638ad58-ce4f-5a64-bb7d-e5839bb1e5e5','11111111-1111-1111-1111-111111111207','Artículo 43.2 — ¿Qué establece este apartado?','Compete a los poderes públicos organizar y tutelar la salud
pública a través de medidas preventivas y de las prestaciones y servicios necesarios. La ley establecerá los derechos y
deberes de todos al respecto.', now(), now()),
('a01e1f2a-3abd-5b87-b184-854c6135cfa9','11111111-1111-1111-1111-111111111207','Artículo 43.3 — ¿Qué establece este apartado?','Los poderes públicos fomentarán la educación sanitaria, la
educación física y el deporte. Asimismo facilitarán la adecuada utilización del ocio.', now(), now()),
('32cd3b43-a2e3-5dd3-b495-57d76b596a68','11111111-1111-1111-1111-111111111207','Artículo 44.1 — ¿Qué establece este apartado?','Los poderes públicos promoverán y tutelarán el acceso a la
cultura, a la que todos tienen derecho.', now(), now()),
('701f0765-9546-5a40-bcfa-f838f8d65c2d','11111111-1111-1111-1111-111111111207','Artículo 44.2 — ¿Qué establece este apartado?','Los poderes públicos promoverán la ciencia y la investigación científica y técnica en beneficio del interés general.', now(), now()),
('3bb77d42-e823-52b7-9239-8e0f5893fc1e','11111111-1111-1111-1111-111111111207','Artículo 45.1 — ¿Qué establece este apartado?','Todos tienen el derecho a disfrutar de un medio ambiente
adecuado para el desarrollo de la persona, así como el
deber de conservarlo.', now(), now()),
('1b78446a-0449-5db7-bd81-09943e477760','11111111-1111-1111-1111-111111111207','Artículo 45.2 — ¿Qué establece este apartado?','Los poderes públicos velarán por la utilización racional de
todos los recursos naturales, con el fin de proteger y mejorar la calidad de la vida y defender y restaurar el medio
ambiente, apoyándose en la indispensable solidaridad
colectiva.', now(), now()),
('0c3ac987-0f65-5563-92c2-318eef9abc15','11111111-1111-1111-1111-111111111207','Artículo 45.3 — ¿Qué establece este apartado?','Para quienes violen lo dispuesto en el apartado anterior, en
los términos que la ley fije se establecerán sanciones penales o, en su caso, administrativas, así como la obligación de
reparar el daño causado.', now(), now()),
('fbd7bb75-7451-54c3-91bf-f6bfee251527','11111111-1111-1111-1111-111111111207','Artículo 46 — ¿Qué establece?','Los poderes públicos garantizarán la conservación y promoverán el enriquecimiento del patrimonio histórico, cultural y artístico de los pueblos de España y de los bienes que lo integran,
cualquiera que sea su régimen jurídico y su titularidad. La ley
penal sancionará los atentados contra este patrimonio.', now(), now()),
('4aaa139d-39bd-585f-9afa-bd67aef67ba0','11111111-1111-1111-1111-111111111207','Artículo 47 — ¿Qué establece?','Todos los españoles tienen derecho a disfrutar de una vivienda
digna y adecuada. Los poderes públicos promoverán las condiciones necesarias y establecerán las normas pertinentes para
hacer efectivo este derecho, regulando la utilización del suelo
de acuerdo con el interés general para impedir la especulación.
La comunidad participará en las plusvalías que genere la acción
urbanística de los entes públicos.', now(), now()),
('2994104e-ad12-5d92-b0d4-103082418bc1','11111111-1111-1111-1111-111111111207','Artículo 48 — ¿Qué establece?','Los poderes públicos promoverán las condiciones para la participación libre y eficaz de la juventud en el desarrollo político,
social, económico y cultural.', now(), now()),
('ccf0cb12-7e46-503f-b3be-e15296daba6d','11111111-1111-1111-1111-111111111207','Artículo 49.1 — ¿Qué establece este apartado?','Las personas con discapacidad ejercen los derechos previstos en este Título en condiciones de libertad e igualdad reales y efectivas. Se regulará por ley la protección especial que
sea necesaria para dicho ejercicio.', now(), now()),
('e0b1fbac-42d8-50f3-82fa-7c8e7fe99ff4','11111111-1111-1111-1111-111111111207','Artículo 49.2 — ¿Qué establece este apartado?','Los poderes públicos impulsarán las políticas que garanticen
la plena autonomía personal y la inclusión social de las personas con discapacidad, en entornos universalmente accesibles. Asimismo, fomentarán la participación de sus
organizaciones, en los términos que la ley establezca. Se
atenderán particularmente las necesidades específicas de
las mujeres y los menores con discapacidad.', now(), now()),
('69105ca0-cd50-57de-a7ee-0e450f587830','11111111-1111-1111-1111-111111111207','Artículo 50 — ¿Qué establece?','Los poderes públicos garantizarán, mediante pensiones adecuadas y periódicamente actualizadas, la suficiencia económica a
los ciudadanos durante la tercera edad. Asimismo, y con independencia de las obligaciones familiares, promoverán su bienestar mediante un sistema de servicios sociales que atenderán
sus problemas específicos de salud, vivienda, cultura y ocio.', now(), now()),
('e40dbc16-9ec8-5b0f-8cf3-7f3aaa66baea','11111111-1111-1111-1111-111111111208','Artículo 51.1 — ¿Qué establece este apartado?','Los poderes públicos garantizarán la defensa de los consumidores y usuarios, protegiendo, mediante procedimientos
eficaces, la seguridad, la salud y los legítimos intereses económicos de los mismos.', now(), now()),
('4868e294-3768-5d2e-9e51-a48f2270f8fc','11111111-1111-1111-1111-111111111208','Artículo 51.2 — ¿Qué establece este apartado?','L os poderes públicos promoverán la información y la educación de los consumidores y usuarios, fomentarán sus organizaciones y oirán a éstas en las cuestiones que puedan
afectar a aquéllos, en los términos que la ley establezca.', now(), now()),
('57e10d05-1d3d-5cd0-88f1-96137357a67a','11111111-1111-1111-1111-111111111208','Artículo 51.3 — ¿Qué establece este apartado?','En el marco de lo dispuesto por los apartados anteriores, la
ley regulará el comercio interior y el régimen de autorización de productos comerciales.', now(), now()),
('8c93e012-89eb-56d4-a7a3-b4d2ab77c819','11111111-1111-1111-1111-111111111208','Artículo 52 — ¿Qué establece?','La ley regulará las organizaciones profesionales que contribuyan
a la defensa de los intereses económicos que les sean propios. Su
estructura interna y funcionamiento deberán ser democráticos.
CAPÍTULO CUARTO
de las gaRantías de las libeRtades y deRechos fundamentales', now(), now()),
('7f862129-63fa-57a0-94c9-3802eba8a38b','11111111-1111-1111-1111-111111111208','Artículo 53.1 — ¿Qué establece este apartado?','Los derechos y libertades reconocidos en el Capítulo
segundo del presente Título vinculan a todos los poderes
públicos. Sólo por ley, que en todo caso deberá respetar su
contenido esencial, podrá regularse el ejercicio de tales
derechos y libertades, que se tutelarán de acuerdo con lo
previsto en el artículo 161, 1, a).', now(), now()),
('379df7a2-539b-5c4b-a9b1-33e967a4e9c4','11111111-1111-1111-1111-111111111208','Artículo 53.2 — ¿Qué establece este apartado?','Cualquier ciudadano podrá recabar la tutela de las libertades y derechos reconocidos en el artículo 14 y la Sección
primera del Capítulo segundo ante los Tribunales ordinarios
por un procedimiento basado en los principios de preferencia y sumariedad y, en su caso, a través del recurso de
amparo ante el Tribunal Constitucional. Este último recurso
será aplicable a la objeción de conciencia reconocida en el
artículo 30.', now(), now()),
('005b69ec-ece4-57d4-80ae-1fb16ae920c3','11111111-1111-1111-1111-111111111208','Artículo 53.3 — ¿Qué establece este apartado?','El reconocimiento, el respeto y la protección de los principios reconocidos en el Capítulo tercero informarán la legislación positiva, la práctica judicial y la actuación de los
poderes públicos. Sólo podrán ser alegados ante la Jurisdicción ordinaria de acuerdo con lo que dispongan las leyes
que los desarrollen.', now(), now()),
('d9e84b4f-2622-528f-bc67-97849a9e7a6b','11111111-1111-1111-1111-111111111208','Artículo 54 — ¿Qué establece?','Una ley orgánica regulará la institución del Defensor del Pueblo,
como alto comisionado de las Cortes Generales, designado por
éstas para la defensa de los derechos comprendidos en este
Título, a cuyo efecto podrá supervisar la actividad de la Administración, dando cuenta a las Cortes Generales.
CAPÍTULO QUINTO
de la suspensión de los deRechos y libeRtades', now(), now()),
('0f79db40-7bbc-5ae6-8b71-d4b4ad664fd3','11111111-1111-1111-1111-111111111208','Artículo 55.1 — ¿Qué establece este apartado?','Los derechos reconocidos en los artículos 17, 18, apartados
2 y 3, artículos 19, 20, apartados 1, a) y d), y 5, artículos 21,
28, apartado 2, y artículo 37, apartado 2, podrán ser suspendidos cuando se acuerde la declaración del estado de
excepción o de sitio en los términos previstos en la Constitución. Se exceptúa de lo establecido anteriormente el
apartado 3 del artículo 17 para el supuesto de declaración
de estado de excepción.', now(), now()),
('9c708991-8a37-5dd2-901d-d2d6847091d4','11111111-1111-1111-1111-111111111208','Artículo 55.2 — ¿Qué establece este apartado?','Una ley orgánica podrá determinar la forma y los casos en
los que, de forma individual y con la necesaria intervención
judicial y el adecuado control parlamentario, los derechos
reconocidos en los artículos 17, apartado 2, y 18, apartados
2 y 3, pueden ser suspendidos para personas determinadas,
en relación con las investigaciones correspondientes a la
actuación de bandas armadas o elementos terroristas.
La utilización injustificada o abusiva de las facultades reconocidas
en dicha ley orgánica producirá responsabilidad penal, como violación de los derechos y libertades reconocidos por las leyes.
TÍTULO II
De la Corona', now(), now()),
('2658ec02-7247-5671-87ff-c50dd23a792f','11111111-1111-1111-1111-111111111209','Artículo 56.1 — ¿Qué establece este apartado?','El Rey es el Jefe del Estado, símbolo de su unidad y permanencia, arbitra y modera el funcionamiento regular de las
instituciones, asume la más alta representación del Estado
español en las relaciones internacionales, especialmente con
las naciones de su comunidad histórica, y ejerce las funciones
que le atribuyen expresamente la Constitución y las leyes.', now(), now()),
('03c5c6fa-de30-5468-b2b7-6025f1263a46','11111111-1111-1111-1111-111111111209','Artículo 56.2 — ¿Qué establece este apartado?','Su título es el de Rey de España y podrá utilizar los demás
que correspondan a la Corona.', now(), now()),
('74cf59b3-ed7b-52a5-8fad-2cd3463e4721','11111111-1111-1111-1111-111111111209','Artículo 56.3 — ¿Qué establece este apartado?','La persona del Rey es inviolable y no está sujeta a responsabilidad. Sus actos estarán siempre refrendados en la forma
establecida en el artículo 64, careciendo de validez sin dicho
refrendo, salvo lo dispuesto en el artículo 65, 2.', now(), now()),
('9c071f73-965f-55d5-9588-be5509333baf','11111111-1111-1111-1111-111111111209','Artículo 57.1 — ¿Qué establece este apartado?','La Corona de España es hereditaria en los sucesores de
S. M. Don Juan Carlos I de Borbón, legítimo heredero de la
dinastía histórica. La sucesión en el trono seguirá el orden
regular de primogenitura y representación, siendo preferida
siempre la línea anterior a las posteriores; en la misma línea,
el grado más próximo al más remoto; en el mismo grado, el
varón a la mujer, y en el mismo sexo, la persona de más
edad a la de menos.', now(), now()),
('835e2a89-6a47-5d06-a686-d6683205b66f','11111111-1111-1111-1111-111111111209','Artículo 57.2 — ¿Qué establece este apartado?','El Príncipe heredero, desde su nacimiento o desde que se
produzca el hecho que origine el llamamiento, tendrá la dignidad de Príncipe de Asturias y los demás títulos vinculados
tradicionalmente al sucesor de la Corona de España.', now(), now()),
('476a7b20-edd1-5e91-ae30-35c7d18bd1b5','11111111-1111-1111-1111-111111111209','Artículo 57.3 — ¿Qué establece este apartado?','Extinguidas todas las líneas llamadas en Derecho, las Cortes
Generales proveerán a la sucesión en la Corona en la forma
que más convenga a los intereses de España.', now(), now()),
('13ee9e1f-d6bf-5a1e-bdc0-141f9243ef66','11111111-1111-1111-1111-111111111209','Artículo 57.4 — ¿Qué establece este apartado?','Aquellas personas que teniendo derecho a la sucesión en el
trono contrajeren matrimonio contra la expresa prohibición
del Rey y de las Cortes Generales, quedarán excluidas en la
sucesión a la Corona por sí y sus descendientes.', now(), now()),
('9d2f179a-b936-5f20-a44d-b46f3815cee2','11111111-1111-1111-1111-111111111209','Artículo 57.5 — ¿Qué establece este apartado?','Las abdicaciones y renuncias y cualquier duda de hecho o
de derecho que ocurra en el orden de sucesión a la Corona
se resolverán por una ley orgánica.', now(), now()),
('b9e0c5fc-5ca1-5bc8-a02e-efa774ff84eb','11111111-1111-1111-1111-111111111209','Artículo 58 — ¿Qué establece?','La Reina consorte o el consorte de la Reina no podrán asumir
funciones constitucionales, salvo lo dispuesto para la Regencia.', now(), now()),
('4e2fc09a-e1bc-5abf-ae37-08457493fb95','11111111-1111-1111-1111-111111111209','Artículo 59.1 — ¿Qué establece este apartado?','Cuando el Rey fuere menor de edad, el padre o la madre
del Rey y, en su defecto, el pariente mayor de edad más
próximo a suceder en la Corona, según el orden establecido
en la Constitución, entrará a ejercer inmediatamente la
Regencia y la ejercerá durante el tiempo de la minoría de
edad del Rey.', now(), now()),
('091f5f70-4690-5e0f-a5ad-a1711ab7c330','11111111-1111-1111-1111-111111111209','Artículo 59.2 — ¿Qué establece este apartado?','Si el Rey se inhabilitare para el ejercicio de su autoridad y la
imposibilidad fuere reconocida por las Cortes Generales,
entrará a ejercer inmediatamente la Regencia el Príncipe
heredero de la Corona, si fuere mayor de edad. Si no lo fuere,
se procederá de la manera prevista en el apartado anterior,
hasta que el Príncipe heredero alcance la mayoría de edad.', now(), now()),
('6e153ff1-6ab8-54e4-a190-ed88c57e9e84','11111111-1111-1111-1111-111111111209','Artículo 59.3 — ¿Qué establece este apartado?','Si no hubiere ninguna persona a quien corresponda la
Regencia, ésta será nombrada por las Cortes Generales, y
se compondrá de una, tres o cinco personas.', now(), now()),
('e87f0987-91da-5d4e-94ba-7d59f5ac4d63','11111111-1111-1111-1111-111111111209','Artículo 59.4 — ¿Qué establece este apartado?','Para ejercer la Regencia es preciso ser español y mayor de
edad.', now(), now()),
('26213730-3b41-508a-a76f-e730dfa8b10f','11111111-1111-1111-1111-111111111209','Artículo 59.5 — ¿Qué establece este apartado?','La Regencia se ejercerá por mandato constitucional y siempre en nombre del Rey.', now(), now()),
('63e8ba49-0ef4-55f1-b484-8dae70a00dec','11111111-1111-1111-1111-111111111209','Artículo 60.1 — ¿Qué establece este apartado?','Será tutor del Rey menor la persona que en su testamento
hubiese nombrado el Rey difunto, siempre que sea mayor
de edad y español de nacimiento; si no lo hubiese nombrado, será tutor el padre o la madre mientras permanezcan
viudos. En su defecto, lo nombrarán las Cortes Generales,
pero no podrán acumularse los cargos de Regente y de tutor
sino en el padre, madre o ascendientes directos del Rey.', now(), now()),
('5e4a2c42-19fa-541c-8097-93aaeb57d7bf','11111111-1111-1111-1111-111111111209','Artículo 60.2 — ¿Qué establece este apartado?','El ejercicio de la tutela es también incompatible con el de
todo cargo o representación política.', now(), now()),
('284363bd-e814-5799-9c66-c6063720684e','11111111-1111-1111-1111-111111111209','Artículo 61.1 — ¿Qué establece este apartado?','El Rey, al ser proclamado ante las Cortes Generales, prestará juramento de desempeñar fielmente sus funciones,
guardar y hacer guardar la Constitución y las leyes y respetar los derechos de los ciudadanos y de las Comunidades
Autónomas.', now(), now()),
('3f231198-dd3e-51ce-8af8-963d396dfc3c','11111111-1111-1111-1111-111111111209','Artículo 61.2 — ¿Qué establece este apartado?','El Príncipe heredero, al alcanzar la mayoría de edad, y el
Regente o Regentes al hacerse cargo de sus funciones, prestarán el mismo juramento, así como el de fidelidad al Rey.', now(), now()),
('29404faf-4aef-5134-a666-886a285ccbdd','11111111-1111-1111-1111-111111111209','Artículo 62 — ¿Qué establece?','Corresponde al Rey:
a) Sancionar y promulgar las leyes.
b) Convocar y disolver las Cortes Generales y convocar
elecciones en los términos previstos en la Constitución.
c) Convocar a referéndum en los casos previstos en la
Constitución.
d) Proponer el candidato a Presidente del Gobierno y, en
su caso, nombrarlo, así como poner fin a sus funciones
en los términos previstos en la Constitución.
e) Nombrar y separar a los miembros del Gobierno, a propuesta de su Presidente.
f) Expedir los decretos acordados en el Consejo de Ministros, conferir los empleos civiles y militares y conceder
honores y distinciones con arreglo a las leyes.
g) Ser informado de los asuntos de Estado y presidir, a
estos efectos, las sesiones del Consejo de Ministros,
cuando lo estime oportuno, a petición del Presidente
del Gobierno.
h) El mando supremo de las Fuerzas Armadas.
i) Ejercer el derecho de gracia con arreglo a la ley, que no
podrá autorizar indultos generales.
j) El Alto Patronazgo de las Reales Academias.', now(), now()),
('a539369a-5f60-5157-9bb2-a366865666f3','11111111-1111-1111-1111-111111111209','Artículo 63.1 — ¿Qué establece este apartado?','El Rey acredita a los embajadores y otros representantes
diplomáticos. Los representantes extranjeros en España
están acreditados ante él.', now(), now()),
('827d2e92-fa71-5b6b-86eb-a7b10ac33443','11111111-1111-1111-1111-111111111209','Artículo 63.2 — ¿Qué establece este apartado?','Al Rey corresponde manifestar el consentimiento del Estado
para obligarse internacionalmente por medio de tratados,
de conformidad con la Constitución y las leyes.', now(), now()),
('2bd81784-b0fb-56a3-8977-6d28c263864e','11111111-1111-1111-1111-111111111209','Artículo 63.3 — ¿Qué establece este apartado?','Al Rey corresponde, previa autorización de las Cortes Generales, declarar la guerra y hacer la paz.', now(), now()),
('be4c68b1-8666-56ec-8c00-84e842ffaf86','11111111-1111-1111-1111-111111111209','Artículo 64.1 — ¿Qué establece este apartado?','Los actos del Rey serán refrendados por el Presidente del
Gobierno y, en su caso, por los Ministros competentes. La
propuesta y el nombramiento del Presidente del Gobierno,
y la disolución prevista en el artículo 99, serán refrendados
por el Presidente del Congreso.', now(), now()),
('9d129434-da34-58a0-95f3-3a1c48b47c43','11111111-1111-1111-1111-111111111209','Artículo 64.2 — ¿Qué establece este apartado?','De los actos del Rey serán responsables las personas que los
refrenden.', now(), now()),
('85740c27-03ce-5308-a468-007d57f1cfaa','11111111-1111-1111-1111-111111111209','Artículo 65.1 — ¿Qué establece este apartado?','El Rey recibe de los Presupuestos del Estado una cantidad
global para el sostenimiento de su Familia y Casa, y distribuye libremente la misma.', now(), now()),
('b1fa8936-d203-5111-8728-de01cc21c72d','11111111-1111-1111-1111-111111111209','Artículo 65.2 — ¿Qué establece este apartado?','El Rey nombra y releva libremente a los miembros civiles y
militares de su Casa.
TÍTULO III
De las Cortes Generales
CAPÍTULO PRIMERO
de las cámaRas', now(), now()),
('b3bd43a6-d6a6-5100-bc42-026eb510f29d','11111111-1111-1111-1111-111111111209','Artículo 66.1 — ¿Qué establece este apartado?','Las Cortes Generales representan al pueblo español y están
formadas por el Congreso de los Diputados y el Senado.', now(), now()),
('233048a9-0456-5960-bae0-b21d9c328958','11111111-1111-1111-1111-111111111209','Artículo 66.2 — ¿Qué establece este apartado?','Las Cortes Generales ejercen la potestad legislativa del
Estado, aprueban sus Presupuestos, controlan la acción del
Gobierno y tienen las demás competencias que les atribuya
la Constitución.', now(), now()),
('5fb3ef05-4c0a-5ab7-90b5-8bcedbfb9c30','11111111-1111-1111-1111-111111111209','Artículo 66.3 — ¿Qué establece este apartado?','Las Cortes Generales son inviolables.', now(), now()),
('862eae3a-1ecf-5a9d-b20f-40b45292ff71','11111111-1111-1111-1111-111111111209','Artículo 67.1 — ¿Qué establece este apartado?','Nadie podrá ser miembro de las dos Cámaras simultáneamente, ni acumular el acta de una Asamblea de Comunidad
Autónoma con la de Diputado al Congreso.', now(), now()),
('d0a7ef57-f346-5c93-be4b-2d4176fbc001','11111111-1111-1111-1111-111111111209','Artículo 67.2 — ¿Qué establece este apartado?','Los miembros de las Cortes Generales no estarán ligados
por mandato imperativo.', now(), now()),
('9db083ff-8452-5587-8235-25a066245979','11111111-1111-1111-1111-111111111209','Artículo 67.3 — ¿Qué establece este apartado?','Las reuniones de Parlamentarios que se celebren sin convocatoria reglamentaria no vincularán a las Cámaras, y no
podrán ejercer sus funciones ni ostentar sus privilegios.', now(), now()),
('103a119e-4824-5e7f-b2df-a4108441b38b','11111111-1111-1111-1111-111111111209','Artículo 68.1 — ¿Qué establece este apartado?','El Congreso se compone de un mínimo de 300 y un máximo
de 400 Diputados, elegidos por sufragio universal, libre,
igual, directo y secreto, en los términos que establezca la ley.', now(), now()),
('9e3a3343-b03a-54c0-8bc9-09fdda38fb97','11111111-1111-1111-1111-111111111209','Artículo 68.2 — ¿Qué establece este apartado?','La circunscripción electoral es la provincia. Las poblaciones
de Ceuta y Melilla estarán representadas cada una de ellas
por un Diputado. La ley distribuirá el número total de Diputados, asignando una representación mínima inicial a cada
circunscripción y distribuyendo los demás en proporción a
la población.', now(), now()),
('1315ada7-9e59-54ec-9627-68ca207b2fb3','11111111-1111-1111-1111-111111111209','Artículo 68.3 — ¿Qué establece este apartado?','La elección se verificará en cada circunscripción atendiendo
a criterios de representación proporcional.', now(), now()),
('d9362256-622d-531c-a68c-742a11cd8ebe','11111111-1111-1111-1111-111111111209','Artículo 68.4 — ¿Qué establece este apartado?','El Congreso es elegido por cuatro años. El mandato de los
Diputados termina cuatro años después de su elección o el
día de la disolución de la Cámara.', now(), now()),
('c6b568a3-8352-5b78-9964-ce015a4c1a18','11111111-1111-1111-1111-111111111209','Artículo 68.5 — ¿Qué establece este apartado?','Son electores y elegibles todos los españoles que estén en
pleno uso de sus derechos políticos.
La ley reconocerá y el Estado facilitará el ejercicio del derecho de sufragio a los españoles que se encuentren fuera del
territorio de España.', now(), now()),
('02eec33b-b3e8-5b7b-836a-9f10325c4b48','11111111-1111-1111-1111-111111111209','Artículo 68.6 — ¿Qué establece este apartado?','Las elecciones tendrán lugar entre los treinta días y sesenta
días desde la terminación del mandato. El Congreso electo
deberá ser convocado dentro de los veinticinco días siguientes a la celebración de las elecciones.', now(), now()),
('dbfb601b-cbaa-5198-a8cf-894368960758','11111111-1111-1111-1111-111111111209','Artículo 69.1 — ¿Qué establece este apartado?','El Senado es la Cámara de representación territorial.', now(), now()),
('728affa0-08e0-592c-992b-587725c0a313','11111111-1111-1111-1111-111111111209','Artículo 69.2 — ¿Qué establece este apartado?','En cada provincia se elegirán cuatro Senadores por sufragio
universal, libre, igual, directo y secreto por los votantes de
cada una de ellas, en los términos que señale una ley orgánica.', now(), now()),
('b3f96b31-f65c-5a50-ba1a-1a560c61c0e5','11111111-1111-1111-1111-111111111209','Artículo 69.3 — ¿Qué establece este apartado?','En las provincias insulares, cada isla o agrupación de ellas,
con Cabildo o Consejo Insular, constituirá una circunscripción
a efectos de elección de Senadores, correspondiendo tres a
cada una de las islas mayores –Gran Canaria, Mallorca y Tenerife– y uno a cada una de las siguientes islas o agrupaciones:
Ibiza-Formentera, Menorca, Fuerteventura, Gomera, Hierro,
Lanzarote y La Palma.', now(), now()),
('a2de9cd6-fbfc-5ad9-9038-054297de4987','11111111-1111-1111-1111-111111111209','Artículo 69.4 — ¿Qué establece este apartado?','Las poblaciones de Ceuta y Melilla elegirán cada una de
ellas dos Senadores.', now(), now()),
('41dfe267-5e7d-5a96-b4ae-fcc62af7e9fc','11111111-1111-1111-1111-111111111209','Artículo 69.5 — ¿Qué establece este apartado?','Las Comunidades Autónomas designarán además un Senador y otro más por cada millón de habitantes de su respectivo territorio. La designación corresponderá a la Asamblea
legislativa o, en su defecto, al órgano colegiado superior de
la Comunidad Autónoma, de acuerdo con lo que establezcan los Estatutos, que asegurarán, en todo caso, la adecuada representación proporcional.', now(), now()),
('0b02a743-5fcd-55af-a823-a2356eb3359d','11111111-1111-1111-1111-111111111209','Artículo 69.6 — ¿Qué establece este apartado?','El Senado es elegido por cuatro años. El mandato de los
Senadores termina cuatro años después de su elección o el
día de la disolución de la Cámara.', now(), now()),
('64f23492-aef6-52fe-baac-6db79e39f2c4','11111111-1111-1111-1111-111111111209','Artículo 70.1 — ¿Qué establece este apartado?','La ley electoral determinará las causas de inelegibilidad e
incompatibilidad de los Diputados y Senadores, que comprenderán, en todo caso:
a) A los componentes del Tribunal Constitucional.
b) A los altos cargos de la Administración del Estado que
determine la ley, con la excepción de los miembros del
Gobierno.
c) Al Defensor del Pueblo.
d) A los Magistrados, Jueces y Fiscales en activo.
e) A los militares profesionales y miembros de las Fuerzas
y Cuerpos de Seguridad y Policía en activo.
f) A los miembros de las Juntas Electorales.', now(), now()),
('00f39d83-caf1-53c5-a45e-86cd19e07e3e','11111111-1111-1111-1111-111111111209','Artículo 70.2 — ¿Qué establece este apartado?','La validez de las actas y credenciales de los miembros de
ambas Cámaras estará sometida al control judicial, en los
términos que establezca la ley electoral.', now(), now()),
('0cf9ad45-2463-55e0-b5fa-e6f7c21f7e52','11111111-1111-1111-1111-111111111209','Artículo 71.1 — ¿Qué establece este apartado?','Los Diputados y Senadores gozarán de inviolabilidad por las
opiniones manifestadas en el ejercicio de sus funciones.', now(), now()),
('978a665f-e203-5694-9f54-657c905de5bd','11111111-1111-1111-1111-111111111209','Artículo 71.2 — ¿Qué establece este apartado?','Durante el período de su mandato los Diputados y Senadores gozarán asimismo de inmunidad y sólo podrán ser detenidos en caso de flagrante delito. No podrán ser inculpados
ni procesados sin la previa autorización de la Cámara respectiva.', now(), now()),
('9ec1add6-9246-5c1a-afc4-688be412b714','11111111-1111-1111-1111-111111111209','Artículo 71.3 — ¿Qué establece este apartado?','En las causas contra Diputados y Senadores será competente la Sala de lo Penal del Tribunal Supremo.', now(), now()),
('ffa1e92e-232d-51b5-abbb-8eecd0092090','11111111-1111-1111-1111-111111111209','Artículo 71.4 — ¿Qué establece este apartado?','Los Diputados y Senadores percibirán una asignación que
será fijada por las respectivas Cámaras.', now(), now()),
('7efd7d47-4c98-5a67-b96f-dfd4598dda44','11111111-1111-1111-1111-111111111209','Artículo 72.1 — ¿Qué establece este apartado?','Las Cámaras establecen sus propios Reglamentos, aprueban
autónomamente sus presupuestos y, de común acuerdo,
regulan el Estatuto del Personal de las Cortes Generales. Los
Reglamentos y su reforma serán sometidos a una votación
final sobre su totalidad, que requerirá la mayoría absoluta.', now(), now()),
('b65d418d-518c-590c-b533-551839b44b1d','11111111-1111-1111-1111-111111111209','Artículo 72.2 — ¿Qué establece este apartado?','Las Cámaras eligen sus respectivos Presidentes y los demás
miembros de sus Mesas. Las sesiones conjuntas serán presididas por el Presidente del Congreso y se regirán por un
Reglamento de las Cortes Generales aprobado por mayoría
absoluta de cada Cámara.', now(), now()),
('da179691-49e5-571b-9626-3f9705a6d384','11111111-1111-1111-1111-111111111209','Artículo 72.3 — ¿Qué establece este apartado?','Los Presidentes de las Cámaras ejercen en nombre de las
mismas todos los poderes administrativos y facultades de
policía en el interior de sus respectivas sedes.', now(), now()),
('77e0a31a-4c6f-5605-9cd3-d6fd4bc610d8','11111111-1111-1111-1111-111111111209','Artículo 73.1 — ¿Qué establece este apartado?','Las Cámaras se reunirán anualmente en dos períodos ordinarios de sesiones: el primero, de septiembre a diciembre,
y el segundo, de febrero a junio.', now(), now()),
('150bb5b5-3977-5fb9-a874-900163d8c089','11111111-1111-1111-1111-111111111209','Artículo 73.2 — ¿Qué establece este apartado?','Las Cámaras podrán reunirse en sesiones extraordinarias a
petición del Gobierno, de la Diputación Permanente o de la
mayoría absoluta de los miembros de cualquiera de las
Cámaras. Las sesiones extraordinarias deberán convocarse
sobre un orden del día determinado y serán clausuradas una
vez que éste haya sido agotado.', now(), now()),
('fefcca40-40af-5543-8264-bad923f99384','11111111-1111-1111-1111-111111111209','Artículo 74.1 — ¿Qué establece este apartado?','Las Cámaras se reunirán en sesión conjunta para ejercer las
competencias no legislativas que el Título II atribuye expresamente a las Cortes Generales.', now(), now()),
('94aba224-aa98-5f61-958f-0f53b7287f2f','11111111-1111-1111-1111-111111111209','Artículo 74.2 — ¿Qué establece este apartado?','Las decisiones de las Cortes Generales previstas en los artículos 94, 1, 145, 2 y 158, 2, se adoptarán por mayoría de cada
una de las Cámaras. En el primer caso, el procedimiento se
iniciará por el Congreso, y en los otros dos, por el Senado. En
ambos casos, si no hubiera acuerdo entre Senado y Congreso, se intentará obtener por una Comisión Mixta compuesta de igual número de Diputados y Senadores. La
Comisión presentará un texto que será votado por ambas
Cámaras. Si no se aprueba en la forma establecida, decidirá
el Congreso por mayoría absoluta.', now(), now()),
('976dd755-af60-5833-a98a-89d1532e3249','11111111-1111-1111-1111-111111111209','Artículo 75.1 — ¿Qué establece este apartado?','Las Cámaras funcionarán en Pleno y por Comisiones.', now(), now()),
('938598da-5be7-5eb8-8dc8-bdc2bc986366','11111111-1111-1111-1111-111111111209','Artículo 75.2 — ¿Qué establece este apartado?','Las Cámaras podrán delegar en las Comisiones Legislativas
Permanentes la aprobación de proyectos o proposiciones
de ley. El Pleno podrá, no obstante, recabar en cualquier
momento el debate y votación de cualquier proyecto o proposición de ley que haya sido objeto de esta delegación.', now(), now()),
('0322fe91-4827-5be9-bc29-4ec541d82902','11111111-1111-1111-1111-111111111209','Artículo 75.3 — ¿Qué establece este apartado?','Quedan exceptuados de lo dispuesto en el apartado anterior la reforma constitucional, las cuestiones internacionales,
las leyes orgánicas y de bases y los Presupuestos Generales
del Estado.', now(), now()),
('2a90df1c-1625-5718-ad88-2c59c875d423','11111111-1111-1111-1111-111111111209','Artículo 76.1 — ¿Qué establece este apartado?','El Congreso y el Senado, y, en su caso, ambas Cámaras
conjuntamente, podrán nombrar Comisiones de investigación sobre cualquier asunto de interés público. Sus conclusiones no serán vinculantes para los Tribunales, ni afectarán
a las resoluciones judiciales, sin perjuicio de que el resultado
de la investigación sea comunicado al Ministerio Fiscal para
el ejercicio, cuando proceda, de las acciones oportunas.', now(), now()),
('01732d7d-6d6c-5622-88ca-4664dd0faf15','11111111-1111-1111-1111-111111111209','Artículo 76.2 — ¿Qué establece este apartado?','Será obligatorio comparecer a requerimiento de las Cámaras. La ley regulará las sanciones que puedan imponerse por
incumplimiento de esta obligación.', now(), now()),
('a2330991-c02d-5269-9fc1-1d21cd52a678','11111111-1111-1111-1111-111111111209','Artículo 77.1 — ¿Qué establece este apartado?','Las Cámaras pueden recibir peticiones individuales y colectivas, siempre por escrito, quedando prohibida la presentación directa por manifestaciones ciudadanas.', now(), now()),
('a3ec3fbc-a33b-5b48-b56e-75f9934cce84','11111111-1111-1111-1111-111111111209','Artículo 77.2 — ¿Qué establece este apartado?','Las Cámaras pueden remitir al Gobierno las peticiones que
reciban. El Gobierno está obligado a explicarse sobre su
contenido, siempre que las Cámaras lo exijan.', now(), now()),
('66caba8d-23a9-5149-a473-91abe3d3da53','11111111-1111-1111-1111-111111111209','Artículo 78.1 — ¿Qué establece este apartado?','En cada Cámara habrá una Diputación Permanente compuesta por un mínimo de veintiún miembros, que representarán a los grupos parlamentarios, en proporción a su
importancia numérica.', now(), now()),
('27137014-1cad-595f-9b20-54601ea79956','11111111-1111-1111-1111-111111111209','Artículo 78.2 — ¿Qué establece este apartado?','Las Diputaciones Permanentes estarán presididas por el
Presidente de la Cámara respectiva y tendrán como funciones la prevista en el artículo 73, la de asumir las facultades
que correspondan a las Cámaras, de acuerdo con los artículos 86 y 116, en caso de que éstas hubieren sido disueltas o
hubiere expirado su mandato y la de velar por los poderes
de las Cámaras cuando éstas no estén reunidas.', now(), now()),
('0ab6de1c-941e-506c-a83b-63163ead6e01','11111111-1111-1111-1111-111111111209','Artículo 78.3 — ¿Qué establece este apartado?','Expirado el mandato o en caso de disolución, las Diputaciones Permanentes seguirán ejerciendo sus funciones hasta la
constitución de las nuevas Cortes Generales.', now(), now()),
('57a6bed0-2ef1-5e0a-b16c-62cc142fd24b','11111111-1111-1111-1111-111111111209','Artículo 78.4 — ¿Qué establece este apartado?','Reunida la Cámara correspondiente, la Diputación Permanente dará cuenta de los asuntos tratados y de sus decisiones.', now(), now()),
('9ee84931-2aed-5f39-b1ff-e3791273b64e','11111111-1111-1111-1111-111111111209','Artículo 79.1 — ¿Qué establece este apartado?','Para adoptar acuerdos, las Cámaras deben estar reunidas
reglamentariamente y con asistencia de la mayoría de sus
miembros.', now(), now()),
('ba34f908-ebb8-56d2-860e-6e3ba810a242','11111111-1111-1111-1111-111111111209','Artículo 79.2 — ¿Qué establece este apartado?','Dichos acuerdos, para ser válidos, deberán ser aprobados
por la mayoría de los miembros presentes, sin perjuicio de
las mayorías especiales que establezcan la Constitución o las
leyes orgánicas y las que para elección de personas establezcan los Reglamentos de las Cámaras.', now(), now()),
('55c658da-7ab5-5185-b7a5-1029043e05b9','11111111-1111-1111-1111-111111111209','Artículo 79.3 — ¿Qué establece este apartado?','El voto de Senadores y Diputados es personal e indelegable.', now(), now()),
('21ae048d-e339-53be-ae2c-c3fe53d80195','11111111-1111-1111-1111-111111111209','Artículo 80 — ¿Qué establece?','Las sesiones plenarias de las Cámaras serán públicas, salvo
acuerdo en contrario de cada Cámara, adoptado por mayoría
absoluta o con arreglo al Reglamento.
CAPÍTULO SEGUNDO
de la elaboRación de las leyes', now(), now()),
('8feaa41e-4b4e-5d85-aec0-da8faea9a23f','11111111-1111-1111-1111-111111111209','Artículo 81.1 — ¿Qué establece este apartado?','Son leyes orgánicas las relativas al desarrollo de los derechos fundamentales y de las libertades públicas, las que
aprueben los Estatutos de Autonomía y el régimen electoral
general y las demás previstas en la Constitución.', now(), now()),
('cf112d8a-dbae-533f-9b5e-99129d54961d','11111111-1111-1111-1111-111111111209','Artículo 81.2 — ¿Qué establece este apartado?','La aprobación, modificación o derogación de las leyes orgánicas exigirá mayoría absoluta del Congreso, en una votación final sobre el conjunto del proyecto.', now(), now()),
('073e42c5-17da-53c5-8922-42ed95300b84','11111111-1111-1111-1111-111111111209','Artículo 82.1 — ¿Qué establece este apartado?','Las Cortes Generales podrán delegar en el Gobierno la
potestad de dictar normas con rango de ley sobre materias
determinadas no incluidas en el artículo anterior.', now(), now()),
('315e73b7-1aec-573b-99ce-f44b011b7571','11111111-1111-1111-1111-111111111209','Artículo 82.2 — ¿Qué establece este apartado?','La delegación legislativa deberá otorgarse mediante una ley
de bases cuando su objeto sea la formación de textos articulados o por una ley ordinaria cuando se trate de refundir
varios textos legales en uno solo.', now(), now()),
('1f96809e-267d-5a11-9350-619d90a77cc0','11111111-1111-1111-1111-111111111209','Artículo 82.3 — ¿Qué establece este apartado?','La delegación legislativa habrá de otorgarse al Gobierno de
forma expresa para materia concreta y con fijación del plazo
para su ejercicio. La delegación se agota por el uso que de
ella haga el Gobierno mediante la publicación de la norma
correspondiente. No podrá entenderse concedida de modo
implícito o por tiempo indeterminado. Tampoco podrá permitir la subdelegación a autoridades distintas del propio
Gobierno.', now(), now()),
('4a339102-8b9c-5409-9f00-b8aa798d6daa','11111111-1111-1111-1111-111111111209','Artículo 82.4 — ¿Qué establece este apartado?','Las leyes de bases delimitarán con precisión el objeto y
alcance de la delegación legislativa y los principios y criterios que han de seguirse en su ejercicio.', now(), now()),
('ea16f72b-c3de-5a5d-ac2b-3f12c20ecd7e','11111111-1111-1111-1111-111111111209','Artículo 82.5 — ¿Qué establece este apartado?','La autorización para refundir textos legales determinará el
ámbito normativo a que se refiere el contenido de la delegación, especificando si se circunscribe a la mera formulación de un texto único o si se incluye la de regularizar, aclarar
y armonizar los textos legales que han de ser refundidos.', now(), now()),
('8c33e74e-f8ce-532c-bfb3-c7812115ca14','11111111-1111-1111-1111-111111111209','Artículo 82.6 — ¿Qué establece este apartado?','Sin perjuicio de la competencia propia de los Tribunales, las
leyes de delegación podrán establecer en cada caso fórmulas adicionales de control.', now(), now()),
('51e69558-7f4a-5181-9398-d25aedbbbaa3','11111111-1111-1111-1111-111111111209','Artículo 83 — ¿Qué establece?','Las leyes de bases no podrán en ningún caso:
a) Autorizar la modificación de la propia ley de bases.
b) Facultar para dictar normas con carácter retroactivo.', now(), now()),
('304c451c-83f6-5555-aeea-6890cd0f685c','11111111-1111-1111-1111-111111111209','Artículo 84 — ¿Qué establece?','Cuando una proposición de ley o una enmienda fuere contraria
a una delegación legislativa en vigor, el Gobierno está facultado
para oponerse a su tramitación. En tal supuesto, podrá presentarse una proposición de ley para la derogación total o parcial
de la ley de delegación.', now(), now()),
('6b29b224-ba3e-5ce2-81dd-0cd6ef2d783d','11111111-1111-1111-1111-111111111209','Artículo 85 — ¿Qué establece?','Las disposiciones del Gobierno que contengan legislación delegada recibirán el título de Decretos Legislativos.', now(), now()),
('664eeebd-ac15-5008-920b-18f20496be86','11111111-1111-1111-1111-111111111209','Artículo 86.1 — ¿Qué establece este apartado?','En caso de extraordinaria y urgente necesidad, el Gobierno
podrá dictar disposiciones legislativas provisionales que
tomarán la forma de Decretos-leyes y que no podrán afectar
al ordenamiento de las instituciones básicas del Estado, a
los derechos, deberes y libertades de los ciudadanos regulados en el Título I, al régimen de las Comunidades Autónomas ni al Derecho electoral general.', now(), now()),
('d1e6bc3c-79f6-5080-bdeb-936632c530b1','11111111-1111-1111-1111-111111111209','Artículo 86.2 — ¿Qué establece este apartado?','Los Decretos-leyes deberán ser inmediatamente sometidos
a debate y votación de totalidad al Congreso de los Diputados, convocado al efecto si no estuviere reunido, en el plazo
de los treinta días siguientes a su promulgación. El Congreso
habrá de pronunciarse expresamente dentro de dicho plazo
sobre su convalidación o derogación, para lo cual el Reglamento establecerá un procedimiento especial y sumario.', now(), now()),
('04ec7371-3449-5c0b-8319-ddcd4101476b','11111111-1111-1111-1111-111111111209','Artículo 86.3 — ¿Qué establece este apartado?','Durante el plazo establecido en el apartado anterior, las
Cortes podrán tramitarlos como proyectos de ley por el procedimiento de urgencia.', now(), now()),
('e9e5c359-eee3-5f22-826c-dba1d9d12bbe','11111111-1111-1111-1111-111111111209','Artículo 87.1 — ¿Qué establece este apartado?','La iniciativa legislativa corresponde al Gobierno, al Congreso y al Senado, de acuerdo con la Constitución y los
Reglamentos de las Cámaras.', now(), now()),
('d850163e-9b4e-586b-8501-5323a0dbff0e','11111111-1111-1111-1111-111111111209','Artículo 87.2 — ¿Qué establece este apartado?','Las Asambleas de las Comunidades Autónomas podrán solicitar del Gobierno la adopción de un proyecto de ley o remitir a la Mesa del Congreso una proposición de ley, delegando
ante dicha Cámara un máximo de tres miembros de la
Asamblea encargados de su defensa.', now(), now()),
('eacae171-16fe-5ae0-ae56-f67e90a288d2','11111111-1111-1111-1111-111111111209','Artículo 87.3 — ¿Qué establece este apartado?','Una ley orgánica regulará las formas de ejercicio y requisitos
de la iniciativa popular para la presentación de proposiciones de ley. En todo caso se exigirán no menos de 500.000
firmas acreditadas. No procederá dicha iniciativa en materias propias de ley orgánica, tributarias o de carácter internacional, ni en lo relativo a la prerrogativa de gracia.', now(), now()),
('f6c24be7-0ee4-5922-9c96-a906bf62d91d','11111111-1111-1111-1111-111111111209','Artículo 88 — ¿Qué establece?','Los proyectos de ley serán aprobados en Consejo de Ministros,
que los someterá al Congreso, acompañados de una exposición
de motivos y de los antecedentes necesarios para pronunciarse
sobre ellos.', now(), now()),
('ca416e6d-5855-5b24-ad9b-d1f3fec972d5','11111111-1111-1111-1111-111111111209','Artículo 89.1 — ¿Qué establece este apartado?','La tramitación de las proposiciones de ley se regulará por
los Reglamentos de las Cámaras, sin que la prioridad debida
a los proyectos de ley impida el ejercicio de la iniciativa
legislativa en los términos regulados por el artículo 87.', now(), now()),
('7172ce0f-8761-5e95-9db1-54ffa79bf094','11111111-1111-1111-1111-111111111209','Artículo 89.2 — ¿Qué establece este apartado?','Las proposiciones de ley que, de acuerdo con el artículo 87,
tome en consideración el Senado, se remitirán al Congreso
para su trámite en éste como tal proposición.', now(), now()),
('1286296d-2e41-553a-abbe-884133bbb79a','11111111-1111-1111-1111-111111111209','Artículo 90.1 — ¿Qué establece este apartado?','Aprobado un proyecto de ley ordinaria u orgánica por el
Congreso de los Diputados, su Presidente dará inmediata
cuenta del mismo al Presidente del Senado, el cual lo someterá a la deliberación de éste.', now(), now()),
('e5c0ff88-4e27-5ed0-8f53-23d0eb45cd2e','11111111-1111-1111-1111-111111111209','Artículo 90.2 — ¿Qué establece este apartado?','El Senado en el plazo de dos meses, a partir del día de la
recepción del texto, puede, mediante mensaje motivado,
oponer su veto o introducir enmiendas al mismo. El veto
deberá ser aprobado por mayoría absoluta. El proyecto no
podrá ser sometido al Rey para sanción sin que el Congreso
ratifique por mayoría absoluta, en caso de veto, el texto
inicial, o por mayoría simple, una vez transcurridos dos
meses desde la interposición del mismo, o se pronuncie
sobre las enmiendas, aceptándolas o no por mayoría simple.', now(), now()),
('b8a5b4ce-2658-5e23-8671-3015df26cc33','11111111-1111-1111-1111-111111111209','Artículo 90.3 — ¿Qué establece este apartado?','El plazo de dos meses de que el Senado dispone para vetar
o enmendar el proyecto se reducirá al de veinte días naturales en los proyectos declarados urgentes por el Gobierno
o por el Congreso de los Diputados.', now(), now()),
('458807f0-e584-5de9-9ca5-e490561ede07','11111111-1111-1111-1111-111111111209','Artículo 91 — ¿Qué establece?','El Rey sancionará en el plazo de quince días las leyes aprobadas
por las Cortes Generales, y las promulgará y ordenará su inmediata publicación.', now(), now()),
('be9a58e3-c2f8-52d5-a94b-64a3c0436648','11111111-1111-1111-1111-111111111209','Artículo 92.1 — ¿Qué establece este apartado?','Las decisiones políticas de especial trascendencia podrán
ser sometidas a referéndum consultivo de todos los ciudadanos.', now(), now()),
('9c039ffd-8fce-50da-b4e9-606a60e56d2b','11111111-1111-1111-1111-111111111209','Artículo 92.2 — ¿Qué establece este apartado?','El referéndum será convocado por el Rey, mediante propuesta del Presidente del Gobierno, previamente autorizada por el Congreso de los Diputados.', now(), now()),
('bfafa184-917c-5c76-bc46-27a83069451e','11111111-1111-1111-1111-111111111209','Artículo 92.3 — ¿Qué establece este apartado?','Una ley orgánica regulará las condiciones y el procedimiento
de las distintas modalidades de referéndum previstas en
esta Constitución.
CAPÍTULO TERCERO
de los tRatados inteRnacionales', now(), now()),
('bfec3f07-20c9-5590-9bea-6cbfebea8b42','11111111-1111-1111-1111-111111111212','Artículo 93 — ¿Qué establece?','Mediante ley orgánica se podrá autorizar la celebración de tratados por los que se atribuya a una organización o institución
internacional el ejercicio de competencias derivadas de la Constitución. Corresponde a las Cortes Generales o al Gobierno,
según los casos, la garantía del cumplimiento de estos tratados
y de las resoluciones emanadas de los organismos internacionales o supranacionales titulares de la cesión.', now(), now()),
('a1acac11-d417-5def-b5eb-fa1a7e17fec2','11111111-1111-1111-1111-111111111212','Artículo 94.1 — ¿Qué establece este apartado?','La prestación del consentimiento del Estado para obligarse
por medio de tratados o convenios requerirá la previa autorización de las Cortes Generales, en los siguientes casos:
a) Tratados de carácter político.
b) Tratados o convenios de carácter militar.
c) Tratados o convenios que afecten a la integridad territorial del Estado o a los derechos y deberes fundamentales establecidos en el Título I.
d) Tratados o convenios que impliquen obligaciones financieras para la Hacienda Pública.
e) Tratados o convenios que supongan modificación o
derogación de alguna ley o exijan medidas legislativas
para su ejecución.', now(), now()),
('2f6b1560-bdf6-533c-bb0e-7167a6946096','11111111-1111-1111-1111-111111111212','Artículo 94.2 — ¿Qué establece este apartado?','El Congreso y el Senado serán inmediatamente informados
de la conclusión de los restantes tratados o convenios.', now(), now()),
('f16a4668-eade-564c-bceb-ca7999c2ad36','11111111-1111-1111-1111-111111111212','Artículo 95.1 — ¿Qué establece este apartado?','La celebración de un tratado internacional que contenga
estipulaciones contrarias a la Constitución exigirá la previa
revisión constitucional.', now(), now()),
('9942d56f-5728-5562-8105-62c5e4e92c5f','11111111-1111-1111-1111-111111111212','Artículo 95.2 — ¿Qué establece este apartado?','El Gobierno o cualquiera de las Cámaras puede requerir al
Tribunal Constitucional para que declare si existe o no esa
contradicción.', now(), now()),
('796cacf9-1880-5e73-b3af-b1c60d2ba805','11111111-1111-1111-1111-111111111212','Artículo 96.1 — ¿Qué establece este apartado?','Los tratados internacionales válidamente celebrados, una
vez publicados oficialmente en España, formarán parte del
ordenamiento interno. Sus disposiciones sólo podrán ser
derogadas, modificadas o suspendidas en la forma prevista
en los propios tratados o de acuerdo con las normas generales del Derecho internacional.', now(), now()),
('53a090f7-ee71-50dc-8a8e-f9e16e73b9a3','11111111-1111-1111-1111-111111111212','Artículo 96.2 — ¿Qué establece este apartado?','Para la denuncia de los tratados y convenios internacionales
se utilizará el mismo procedimiento previsto para su aprobación en el artículo 94.
TÍTULO IV
Del Gobierno y de la Administración', now(), now()),
('c3b6b158-ba7a-5c57-a1e0-a6de01718e47','11111111-1111-1111-1111-111111111213','Artículo 97 — ¿Qué establece?','El Gobierno dirige la política interior y exterior, la Administración civil y militar y la defensa del Estado. Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución
y las leyes.', now(), now()),
('3437b34d-d620-556f-9e26-604659dcc5e1','11111111-1111-1111-1111-111111111213','Artículo 98.1 — ¿Qué establece este apartado?','El Gobierno se compone del Presidente, de los Vicepresidentes, en su caso, de los Ministros y de los demás miembros que establezca la ley.', now(), now()),
('406c0874-7b89-503a-b3a2-9c0ef5540474','11111111-1111-1111-1111-111111111213','Artículo 98.2 — ¿Qué establece este apartado?','El Presidente dirige la acción del Gobierno y coordina las
funciones de los demás miembros del mismo, sin perjuicio
de la competencia y responsabilidad directa de éstos en su
gestión.', now(), now()),
('9ebb3ecd-9ce7-57a9-9ed0-ca1005176811','11111111-1111-1111-1111-111111111213','Artículo 98.3 — ¿Qué establece este apartado?','Los miembros del Gobierno no podrán ejercer otras funciones representativas que las propias del mandato parlamentario, ni cualquier otra función pública que no derive de su
cargo, ni actividad profesional o mercantil alguna.', now(), now()),
('ff075f72-9568-53b5-87d5-67d517b02169','11111111-1111-1111-1111-111111111213','Artículo 98.4 — ¿Qué establece este apartado?','La ley regulará el estatuto e incompatibilidades de los
miembros del Gobierno.', now(), now()),
('a7d310da-a0ae-5903-b4c9-7a39fd3c212d','11111111-1111-1111-1111-111111111213','Artículo 99.1 — ¿Qué establece este apartado?','Después de cada renovación del Congreso de los Diputados, y en los demás supuestos constitucionales en que así
proceda, el Rey, previa consulta con los representantes
designados por los Grupos políticos con representación parlamentaria, y a través del Presidente del Congreso, propondrá un candidato a la Presidencia del Gobierno.', now(), now()),
('878fe252-bc24-57ca-bdfe-b4069f01c659','11111111-1111-1111-1111-111111111213','Artículo 99.2 — ¿Qué establece este apartado?','El candidato propuesto conforme a lo previsto en el apartado anterior expondrá ante el Congreso de los Diputados
el programa político del Gobierno que pretenda formar y
solicitará la confianza de la Cámara.', now(), now()),
('c7d4b476-3d98-5d48-99bc-459e6af021b8','11111111-1111-1111-1111-111111111213','Artículo 99.3 — ¿Qué establece este apartado?','Si el Congreso de los Diputados, por el voto de la mayoría
absoluta de sus miembros, otorgare su confianza a dicho
candidato, el Rey le nombrará Presidente. De no alcanzarse
dicha mayoría, se someterá la misma propuesta a nueva
votación cuarenta y ocho horas después de la anterior, y la
confianza se entenderá otorgada si obtuviere la mayoría
simple.', now(), now()),
('6f49e6ad-34a3-528f-a6d4-1fc9a544da8c','11111111-1111-1111-1111-111111111213','Artículo 99.4 — ¿Qué establece este apartado?','Si efectuadas las citadas votaciones no se otorgase la confianza para la investidura, se tramitarán sucesivas propuestas
en la forma prevista en los apartados anteriores.', now(), now()),
('a50cfb64-1f9a-573a-93fa-36d68c410a60','11111111-1111-1111-1111-111111111213','Artículo 99.5 — ¿Qué establece este apartado?','Si transcurrido el plazo de dos meses, a partir de la primera
votación de investidura, ningún candidato hubiere obtenido
la confianza del Congreso, el Rey disolverá ambas Cámaras
y convocará nuevas elecciones con el refrendo del Presidente del Congreso.', now(), now()),
('695fc313-b65e-5ca0-9c13-85bd9c72c181','11111111-1111-1111-1111-111111111213','Artículo 100 — ¿Qué establece?','Los demás miembros del Gobierno serán nombrados y separados por el Rey, a propuesta de su Presidente.', now(), now()),
('c060f23b-d3e8-5592-b5ff-6c4337e0ee18','11111111-1111-1111-1111-111111111213','Artículo 101.1 — ¿Qué establece este apartado?','El Gobierno cesa tras la celebración de elecciones generales, en los casos de pérdida de la confianza parlamentaria
previstos en la Constitución, o por dimisión o fallecimiento
de su Presidente.', now(), now()),
('3c8c3c1d-2b96-5a2f-b31f-fd46ab33a168','11111111-1111-1111-1111-111111111213','Artículo 101.2 — ¿Qué establece este apartado?','El Gobierno cesante continuará en funciones hasta la toma
de posesión del nuevo Gobierno.', now(), now()),
('3d3ed3d7-156a-5a1e-bb6c-34c0eef98d32','11111111-1111-1111-1111-111111111213','Artículo 102.1 — ¿Qué establece este apartado?','La responsabilidad criminal del Presidente y los demás
miembros del Gobierno será exigible, en su caso, ante la
Sala de lo Penal del Tribunal Supremo.', now(), now()),
('2492208e-ead6-50dd-959a-22eb6f54584a','11111111-1111-1111-1111-111111111213','Artículo 102.2 — ¿Qué establece este apartado?','Si la acusación fuere por traición o por cualquier delito contra la seguridad del Estado en el ejercicio de sus funciones,
sólo podrá ser planteada por iniciativa de la cuarta parte de
los miembros del Congreso, y con la aprobación de la mayoría absoluta del mismo.', now(), now()),
('b85c0b51-595d-5702-a74a-4a04725b016e','11111111-1111-1111-1111-111111111213','Artículo 102.3 — ¿Qué establece este apartado?','La prerrogativa real de gracia no será aplicable a ninguno de
los supuestos del presente artículo.', now(), now()),
('3628b0bc-8cfc-5f67-b7f9-e12fe3464321','11111111-1111-1111-1111-111111111213','Artículo 103.1 — ¿Qué establece este apartado?','La Administración Pública sirve con objetividad los intereses
generales y actúa de acuerdo con los principios de eficacia,
jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho.', now(), now()),
('6f512f06-65e3-52ab-b854-605575382be4','11111111-1111-1111-1111-111111111213','Artículo 103.2 — ¿Qué establece este apartado?','Los órganos de la Administración del Estado son creados,
regidos y coordinados de acuerdo con la ley.', now(), now()),
('22e75119-1998-56bf-ab3b-cc6098dca2cb','11111111-1111-1111-1111-111111111213','Artículo 103.3 — ¿Qué establece este apartado?','La ley regulará el estatuto de los funcionarios públicos, el
acceso a la función pública de acuerdo con los principios
de mérito y capacidad, las peculiaridades del ejercicio de
su derecho a sindicación, el sistema de incompatibilidades
y las garantías para la imparcialidad en el ejercicio de sus
funciones.', now(), now()),
('af779eff-3d83-5252-82f1-35ae69fe7de9','11111111-1111-1111-1111-111111111213','Artículo 104.1 — ¿Qué establece este apartado?','Las Fuerzas y Cuerpos de seguridad, bajo la dependencia
del Gobierno, tendrán como misión proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad
ciudadana.', now(), now()),
('30f95e40-6c3f-5274-94b4-4522d907b311','11111111-1111-1111-1111-111111111213','Artículo 104.2 — ¿Qué establece este apartado?','Una ley orgánica determinará las funciones, principios básicos de actuación y estatutos de las Fuerzas y Cuerpos de
seguridad.', now(), now()),
('35cf3165-214a-53a7-8a1e-5714110fa883','11111111-1111-1111-1111-111111111213','Artículo 105 — ¿Qué establece?','La ley regulará:
a) La audiencia de los ciudadanos, directamente o a través
de las organizaciones y asociaciones reconocidas por la
ley, en el procedimiento de elaboración de las disposiciones administrativas que les afecten.
b) El acceso de los ciudadanos a los archivos y registros
administrativos, salvo en lo que afecte a la seguridad y
defensa del Estado, la averiguación de los delitos y la
intimidad de las personas.
c) El procedimiento a través del cual deben producirse los
actos administrativos, garantizando, cuando proceda,
la audiencia del interesado.', now(), now()),
('bf250ae6-04ee-5efb-ba59-c126ea825f05','11111111-1111-1111-1111-111111111213','Artículo 106.1 — ¿Qué establece este apartado?','Los Tribunales controlan la potestad reglamentaria y la legalidad de la actuación administrativa, así como el sometimiento de ésta a los fines que la justifican.', now(), now()),
('ce2eba14-7bd0-5574-9378-89afc7121863','11111111-1111-1111-1111-111111111213','Artículo 106.2 — ¿Qué establece este apartado?','Los particulares, en los términos establecidos por la ley, tendrán derecho a ser indemnizados por toda lesión que sufran
en cualquiera de sus bienes y derechos, salvo en los casos
de fuerza mayor, siempre que la lesión sea consecuencia del
funcionamiento de los servicios públicos.', now(), now()),
('bce02aa5-fdf0-53af-bffa-1ca70ca2eb7f','11111111-1111-1111-1111-111111111213','Artículo 107 — ¿Qué establece?','El Consejo de Estado es el supremo órgano consultivo del Gobierno.
Una ley orgánica regulará su composición y competencia.
TÍTULO V
De las relaciones entre el Gobierno y las Cortes Generales', now(), now()),
('3fc32a4c-3bd8-531d-8069-2291f0d47814','11111111-1111-1111-1111-111111111214','Artículo 108 — ¿Qué establece?','El Gobierno responde solidariamente en su gestión política ante
el Congreso de los Diputados.', now(), now()),
('dcda9b7b-4c5c-5cf5-8aa2-e41ebff33f76','11111111-1111-1111-1111-111111111214','Artículo 109 — ¿Qué establece?','Las Cámaras y sus Comisiones podrán recabar, a través de los
Presidentes de aquéllas, la información y ayuda que precisen del
Gobierno y de sus Departamentos y de cualesquiera autoridades del Estado y de las Comunidades Autónomas.', now(), now()),
('116172fb-d74a-5f9a-827a-b56c2aa6744c','11111111-1111-1111-1111-111111111214','Artículo 110.1 — ¿Qué establece este apartado?','Las Cámaras y sus Comisiones pueden reclamar la presencia
de los miembros del Gobierno.', now(), now()),
('020423f2-a6e9-566e-998e-f8875cabe107','11111111-1111-1111-1111-111111111214','Artículo 110.2 — ¿Qué establece este apartado?','Los miembros del Gobierno tienen acceso a las sesiones de
las Cámaras y a sus Comisiones y la facultad de hacerse oír
en ellas, y podrán solicitar que informen ante las mismas
funcionarios de sus Departamentos.', now(), now()),
('3e129cd6-6593-57ec-a754-003d8a5154ac','11111111-1111-1111-1111-111111111214','Artículo 111.1 — ¿Qué establece este apartado?','El Gobierno y cada uno de sus miembros están sometidos a
las interpelaciones y preguntas que se le formulen en las
Cámaras. Para esta clase de debate los Reglamentos establecerán un tiempo mínimo semanal.', now(), now()),
('bd768928-604b-5020-aba2-3fd6af09145c','11111111-1111-1111-1111-111111111214','Artículo 111.2 — ¿Qué establece este apartado?','Toda interpelación podrá dar lugar a una moción en la que
la Cámara manifieste su posición.', now(), now()),
('0a2403c2-8a48-5352-b8a3-97a47c9d1e98','11111111-1111-1111-1111-111111111214','Artículo 112 — ¿Qué establece?','El Presidente del Gobierno, previa deliberación del Consejo de
Ministros, puede plantear ante el Congreso de los Diputados la
cuestión de confianza sobre su programa o sobre una declaración de política general. La confianza se entenderá otorgada
cuando vote a favor de la misma la mayoría simple de los Diputados.', now(), now()),
('66fe5e1f-3e2d-50ce-8316-edd83af6b29b','11111111-1111-1111-1111-111111111214','Artículo 113.1 — ¿Qué establece este apartado?','El Congreso de los Diputados puede exigir la responsabilidad política del Gobierno mediante la adopción por mayoría absoluta de la moción de censura.', now(), now()),
('3f758d54-eda2-5d48-95a2-34913554be16','11111111-1111-1111-1111-111111111214','Artículo 113.2 — ¿Qué establece este apartado?','La moción de censura deberá ser propuesta al menos por la
décima parte de los Diputados, y habrá de incluir un candidato a la Presidencia del Gobierno.', now(), now()),
('771a1b32-9c36-5c5b-b044-7fff082b4500','11111111-1111-1111-1111-111111111214','Artículo 113.3 — ¿Qué establece este apartado?','La moción de censura no podrá ser votada hasta que transcurran cinco días desde su presentación. En los dos primeros días de dicho plazo podrán presentarse mociones
alternativas.', now(), now()),
('a257b612-055b-5029-9236-4da31e2bbf00','11111111-1111-1111-1111-111111111214','Artículo 113.4 — ¿Qué establece este apartado?','Si la moción de censura no fuere aprobada por el Congreso,
sus signatarios no podrán presentar otra durante el mismo
período de sesiones.', now(), now()),
('c85c42ca-b810-5c60-b92e-7ea7b286ceb1','11111111-1111-1111-1111-111111111214','Artículo 114.1 — ¿Qué establece este apartado?','Si el Congreso niega su confianza al Gobierno, éste presentará su dimisión al Rey, procediéndose a continuación a la
designación de Presidente del Gobierno, según lo dispuesto
en el artículo 99.', now(), now()),
('11a8581b-889a-5c21-8763-10537f5104f4','11111111-1111-1111-1111-111111111214','Artículo 114.2 — ¿Qué establece este apartado?','Si el Congreso adopta una moción de censura, el Gobierno
presentará su dimisión al Rey y el candidato incluido en
aquélla se entenderá investido de la confianza de la Cámara
a los efectos previstos en el artículo 99. El Rey le nombrará
Presidente del Gobierno.', now(), now()),
('32ee7fbe-d962-5a0f-a328-0f3a0d880dfc','11111111-1111-1111-1111-111111111214','Artículo 115.1 — ¿Qué establece este apartado?','El Presidente del Gobierno, previa deliberación del Consejo
de Ministros, y bajo su exclusiva responsabilidad, podrá proponer la disolución del Congreso, del Senado o de las Cortes Generales, que será decretada por el Rey. El decreto de
disolución fijará la fecha de las elecciones.', now(), now()),
('43955c8f-b494-5c98-8375-6ea6ffa49061','11111111-1111-1111-1111-111111111214','Artículo 115.2 — ¿Qué establece este apartado?','La propuesta de disolución no podrá presentarse cuando
esté en trámite una moción de censura.', now(), now()),
('488c7dfb-335f-55a1-bbb1-65ca405cc2b6','11111111-1111-1111-1111-111111111214','Artículo 115.3 — ¿Qué establece este apartado?','No procederá nueva disolución antes de que transcurra un
año desde la anterior, salvo lo dispuesto en el artículo 99,
apartado 5.', now(), now()),
('c48b77e2-b06b-58ad-979e-cacfda035250','11111111-1111-1111-1111-111111111214','Artículo 116.1 — ¿Qué establece este apartado?','Una ley orgánica regulará los estados de alarma, de excepción y de sitio, y las competencias y limitaciones correspondientes.', now(), now()),
('73b63018-d5ac-5e53-995b-cf0b0cb3d70a','11111111-1111-1111-1111-111111111214','Artículo 116.2 — ¿Qué establece este apartado?','El estado de alarma será declarado por el Gobierno
mediante decreto acordado en Consejo de Ministros por un
plazo máximo de quince días, dando cuenta al Congreso de
los Diputados, reunido inmediatamente al efecto y sin cuya
autorización no podrá ser prorrogado dicho plazo. El
decreto determinará el ámbito territorial a que se extienden
los efectos de la declaración.', now(), now()),
('18d934f3-3b80-5c39-89a2-5464d55e591a','11111111-1111-1111-1111-111111111214','Artículo 116.3 — ¿Qué establece este apartado?','El estado de excepción será declarado por el Gobierno
mediante decreto acordado en Consejo de Ministros, previa
autorización del Congreso de los Diputados. La autorización
y proclamación del estado de excepción deberá determinar
expresamente los efectos del mismo, el ámbito territorial a
que se extiende y su duración, que no podrá exceder de
treinta días, prorrogables por otro plazo igual, con los mismos requisitos.', now(), now()),
('22099a89-2395-56a9-8133-f541d3622a82','11111111-1111-1111-1111-111111111214','Artículo 116.4 — ¿Qué establece este apartado?','El estado de sitio será declarado por la mayoría absoluta del
Congreso de los Diputados, a propuesta exclusiva del
Gobierno. El Congreso determinará su ámbito territorial,
duración y condiciones.', now(), now()),
('c403c30a-eb4d-5637-ad5f-aa441a2964a2','11111111-1111-1111-1111-111111111214','Artículo 116.5 — ¿Qué establece este apartado?','No podrá procederse a la disolución del Congreso mientras
estén declarados algunos de los estados comprendidos en
el presente artículo, quedando automáticamente convocadas las Cámaras si no estuvieren en período de sesiones. Su
funcionamiento, así como el de los demás poderes constitucionales del Estado, no podrán interrumpirse durante la
vigencia de estos estados.
Disuelto el Congreso o expirado su mandato, si se produjere alguna de las situaciones que dan lugar a cualquiera de
dichos estados, las competencias del Congreso serán asumidas por su Diputación Permanente.', now(), now()),
('3bd09139-2a0c-5ae9-ba11-6db27f8acffe','11111111-1111-1111-1111-111111111214','Artículo 116.6 — ¿Qué establece este apartado?','La declaración de los estados de alarma, de excepción y de
sitio no modificarán el principio de responsabilidad del
Gobierno y de sus agentes reconocidos en la Constitución y
en las leyes.
TÍTULO VI
Del Poder Judicial', now(), now()),
('6580e0bb-f8ed-5799-96b4-14fe346ead65','11111111-1111-1111-1111-111111111214','Artículo 117.1 — ¿Qué establece este apartado?','La justicia emana del pueblo y se administra en nombre del
Rey por Jueces y Magistrados integrantes del poder judicial,
independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.', now(), now()),
('b1d31fd7-0158-5c64-9ea0-9cf9feae4a10','11111111-1111-1111-1111-111111111214','Artículo 117.2 — ¿Qué establece este apartado?','Los Jueces y Magistrados no podrán ser separados, suspendidos, trasladados ni jubilados, sino por alguna de las causas
y con las garantías previstas en la ley.', now(), now()),
('b63d7243-4079-5376-bd1c-ebad45426c3e','11111111-1111-1111-1111-111111111214','Artículo 117.3 — ¿Qué establece este apartado?','El ejercicio de la potestad jurisdiccional en todo tipo de procesos, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a los Juzgados y Tribunales
determinados por las leyes, según las normas de competencia y procedimiento que las mismas establezcan.', now(), now()),
('09eb8c79-5534-5db4-9ef3-7620db01d9d8','11111111-1111-1111-1111-111111111214','Artículo 117.4 — ¿Qué establece este apartado?','Los Juzgados y Tribunales no ejercerán más funciones que
las señaladas en el apartado anterior y las que expresamente les sean atribuidas por ley en garantía de cualquier
derecho.', now(), now()),
('e7642c61-d3d4-5190-9ac8-fcebf099c342','11111111-1111-1111-1111-111111111214','Artículo 117.5 — ¿Qué establece este apartado?','El principio de unidad jurisdiccional es la base de la organización y funcionamiento de los Tribunales. La ley regulará el
ejercicio de la jurisdicción militar en el ámbito estrictamente
castrense y en los supuestos de estado de sitio, de acuerdo
con los principios de la Constitución.', now(), now()),
('e68822cd-7096-5cbd-877f-15c81cd48047','11111111-1111-1111-1111-111111111214','Artículo 117.6 — ¿Qué establece este apartado?','Se prohíben los Tribunales de excepción.', now(), now()),
('8ce37109-6407-546b-a93b-61c1e792dd30','11111111-1111-1111-1111-111111111214','Artículo 118 — ¿Qué establece?','Es obligado cumplir las sentencias y demás resoluciones firmes
de los Jueces y Tribunales, así como prestar la colaboración
requerida por éstos en el curso del proceso y en la ejecución de
lo resuelto.', now(), now()),
('63c77ee9-deb3-5300-995f-c2a513fcd1ce','11111111-1111-1111-1111-111111111214','Artículo 119 — ¿Qué establece?','La justicia será gratuita cuando así lo disponga la ley y, en todo
caso, respecto de quienes acrediten insuficiencia de recursos
para litigar.', now(), now()),
('527a4f61-0af9-5dbb-bf3a-f670ca63e9f6','11111111-1111-1111-1111-111111111214','Artículo 120.1 — ¿Qué establece este apartado?','Las actuaciones judiciales serán públicas, con las excepciones que prevean las leyes de procedimiento.', now(), now()),
('bb74a56b-9a28-5233-b311-8701063f865a','11111111-1111-1111-1111-111111111214','Artículo 120.2 — ¿Qué establece este apartado?','El procedimiento será predominantemente oral, sobre todo
en materia criminal.', now(), now()),
('c8a54d99-6c29-58fa-8bb7-4d0ab94d1ac0','11111111-1111-1111-1111-111111111214','Artículo 120.3 — ¿Qué establece este apartado?','Las sentencias serán siempre motivadas y se pronunciarán
en audiencia pública.', now(), now()),
('74d5bf77-c282-5617-b7cd-cbcc9fb9c73d','11111111-1111-1111-1111-111111111214','Artículo 121 — ¿Qué establece?','Los daños causados por error judicial, así como los que sean
consecuencia del funcionamiento anormal de la Administración
de Justicia, darán derecho a una indemnización a cargo del
Estado, conforme a la ley.', now(), now()),
('28e3c009-15f2-5e46-a09a-3c052ba11b19','11111111-1111-1111-1111-111111111214','Artículo 122.1 — ¿Qué establece este apartado?','La ley orgánica del poder judicial determinará la constitución, funcionamiento y gobierno de los Juzgados y Tribunales, así como el estatuto jurídico de los Jueces y Magistrados
de carrera, que formarán un Cuerpo único, y del personal al
servicio de la Administración de Justicia.', now(), now()),
('56e9157b-69fd-5029-bcd1-57a7bb81e95c','11111111-1111-1111-1111-111111111214','Artículo 122.2 — ¿Qué establece este apartado?','El Consejo General del Poder Judicial es el órgano de
gobierno del mismo. La ley orgánica establecerá su estatuto
y el régimen de incompatibilidades de sus miembros y sus
funciones, en particular en materia de nombramientos,
ascensos, inspección y régimen disciplinario.', now(), now()),
('988cd8c6-01fe-5641-8f07-7a82a8a7a11d','11111111-1111-1111-1111-111111111214','Artículo 122.3 — ¿Qué establece este apartado?','El Consejo General del Poder Judicial estará integrado por
el Presidente del Tribunal Supremo, que lo presidirá, y por
veinte miembros nombrados por el Rey por un período de
cinco años. De éstos, doce entre Jueces y Magistrados de
todas las categorías judiciales, en los términos que establezca la ley orgánica; cuatro a propuesta del Congreso de
los Diputados, y cuatro a propuesta del Senado, elegidos en
ambos casos por mayoría de tres quintos de sus miembros,
entre abogados y otros juristas, todos ellos de reconocida
competencia y con más de quince años de ejercicio en su
profesión.', now(), now()),
('dd446846-e5be-522e-9789-5858d3fc47fb','11111111-1111-1111-1111-111111111214','Artículo 123.1 — ¿Qué establece este apartado?','El Tribunal Supremo, con jurisdicción en toda España, es el
órgano jurisdiccional superior en todos los órdenes, salvo lo
dispuesto en materia de garantías constitucionales.', now(), now()),
('b9c61b3a-67e4-569e-a84e-5808665628ec','11111111-1111-1111-1111-111111111214','Artículo 123.2 — ¿Qué establece este apartado?','El Presidente del Tribunal Supremo será nombrado por el
Rey, a propuesta del Consejo General del Poder Judicial, en
la forma que determine la ley.', now(), now()),
('c091d831-63f6-5211-b7f9-685b9041087c','11111111-1111-1111-1111-111111111214','Artículo 124.1 — ¿Qué establece este apartado?','El Ministerio Fiscal, sin perjuicio de las funciones encomendadas a otros órganos, tiene por misión promover la acción
de la justicia en defensa de la legalidad, de los derechos de
los ciudadanos y del interés público tutelado por la ley, de
oficio o a petición de los interesados, así como velar por la
independencia de los Tribunales y procurar ante éstos la
satisfacción del interés social.', now(), now()),
('a4d7373c-7967-5a31-a687-7e08771c7a96','11111111-1111-1111-1111-111111111214','Artículo 124.2 — ¿Qué establece este apartado?','El Ministerio Fiscal ejerce sus funciones por medio de órganos propios conforme a los principios de unidad de actuación y dependencia jerárquica y con sujeción, en todo caso,
a los de legalidad e imparcialidad.', now(), now()),
('2aad6c24-6ada-537e-bc76-9be3d6c612b3','11111111-1111-1111-1111-111111111214','Artículo 124.3 — ¿Qué establece este apartado?','La ley regulará el estatuto orgánico del Ministerio Fiscal.', now(), now()),
('4cbebd4e-15d4-58d3-90e6-77659da9b4c2','11111111-1111-1111-1111-111111111214','Artículo 124.4 — ¿Qué establece este apartado?','El Fiscal General del Estado será nombrado por el Rey, a
propuesta del Gobierno, oído el Consejo General del Poder
Judicial.', now(), now()),
('eef3264c-7fde-5aaf-8a75-7acf596b8a42','11111111-1111-1111-1111-111111111214','Artículo 125 — ¿Qué establece?','Los ciudadanos podrán ejercer la acción popular y participar en
la Administración de Justicia mediante la institución del Jurado,
en la forma y con respecto a aquellos procesos penales que la
ley determine, así como en los Tribunales consuetudinarios y
tradicionales.', now(), now()),
('e53b95b6-4373-54f7-8cb2-9f124c11740a','11111111-1111-1111-1111-111111111214','Artículo 126 — ¿Qué establece?','La policía judicial depende de los Jueces, de los Tribunales y del
Ministerio Fiscal en sus funciones de averiguación del delito y
descubrimiento y aseguramiento del delincuente, en los términos que la ley establezca.', now(), now()),
('41dc1d87-32af-57d4-a5dd-fc4276fa5916','11111111-1111-1111-1111-111111111214','Artículo 127.1 — ¿Qué establece este apartado?','Los Jueces y Magistrados así como los Fiscales, mientras se
hallen en activo, no podrán desempeñar otros cargos públicos, ni pertenecer a partidos políticos o sindicatos. La ley
establecerá el sistema y modalidades de asociación profesional de los Jueces, Magistrados y Fiscales.', now(), now()),
('b6b57546-3dbd-5c30-8cb0-9dd127fb1678','11111111-1111-1111-1111-111111111214','Artículo 127.2 — ¿Qué establece este apartado?','La ley establecerá el régimen de incompatibilidades de los
miembros del poder judicial, que deberá asegurar la total
independencia de los mismos.
TÍTULO VII
Economía y Hacienda', now(), now()),
('7ca4988a-1b81-5957-8554-340e4b549980','11111111-1111-1111-1111-111111111214','Artículo 128.1 — ¿Qué establece este apartado?','Toda la riqueza del país en sus distintas formas y sea cual
fuere su titularidad está subordinada al interés general.', now(), now()),
('71ad26b3-d7e5-53f5-ae22-3cd1957be0e5','11111111-1111-1111-1111-111111111214','Artículo 128.2 — ¿Qué establece este apartado?','Se reconoce la iniciativa pública en la actividad económica.
Mediante ley se podrá reservar al sector público recursos o
servicios esenciales, especialmente en caso de monopolio y
asimismo acordar la intervención de empresas cuando así lo
exigiere el interés general.', now(), now()),
('2665daad-2774-549e-b26b-5dc211ce333b','11111111-1111-1111-1111-111111111214','Artículo 129.1 — ¿Qué establece este apartado?','La ley establecerá las formas de participación de los interesados en la Seguridad Social y en la actividad de los organismos públicos cuya función afecte directamente a la
calidad de la vida o al bienestar general.', now(), now()),
('ea6a202e-2fb6-57ed-bcbf-bc64cdfbbe07','11111111-1111-1111-1111-111111111214','Artículo 129.2 — ¿Qué establece este apartado?','Los poderes públicos promoverán eficazmente las diversas
formas de participación en la empresa y fomentarán,
mediante una legislación adecuada, las sociedades cooperativas. También establecerán los medios que faciliten el
acceso de los trabajadores a la propiedad de los medios de
producción.', now(), now()),
('8b02c705-1ad2-5116-945e-3aa33497fac6','11111111-1111-1111-1111-111111111214','Artículo 130.1 — ¿Qué establece este apartado?','Los poderes públicos atenderán a la modernización y desarrollo de todos los sectores económicos y, en particular, de
la agricultura, de la ganadería, de la pesca y de la artesanía,
a fin de equiparar el nivel de vida de todos los españoles.', now(), now()),
('d2b47393-6a45-5bb8-89af-6f021ea9a837','11111111-1111-1111-1111-111111111214','Artículo 130.2 — ¿Qué establece este apartado?','Con el mismo fin, se dispensará un tratamiento especial a las
zonas de montaña.', now(), now()),
('ee808b16-3573-5f81-bf61-a9d37eb9f472','11111111-1111-1111-1111-111111111214','Artículo 131.1 — ¿Qué establece este apartado?','El Estado, mediante ley, podrá planificar la actividad económica general para atender a las necesidades colectivas,
equilibrar y armonizar el desarrollo regional y sectorial y
estimular el crecimiento de la renta y de la riqueza y su más
justa distribución.', now(), now()),
('bc3a0d28-bc2e-5de2-9107-4f24fa61dcf0','11111111-1111-1111-1111-111111111214','Artículo 131.2 — ¿Qué establece este apartado?','El Gobierno elaborará los proyectos de planificación, de
acuerdo con las previsiones que le sean suministradas por
las Comunidades Autónomas y el asesoramiento y colaboración de los sindicatos y otras organizaciones profesionales,
empresariales y económicas. A tal fin se constituirá un Consejo, cuya composición y funciones se desarrollarán por ley.', now(), now()),
('8dbd15a8-352c-5350-adb0-30fccc2c5e40','11111111-1111-1111-1111-111111111214','Artículo 132.1 — ¿Qué establece este apartado?','La ley regulará el régimen jurídico de los bienes de dominio
público y de los comunales, inspirándose en los principios
de inalienabilidad, imprescriptibilidad e inembargabilidad,
así como su desafectación.', now(), now()),
('d1ae30ab-536f-5e24-83f0-6e5031c8946a','11111111-1111-1111-1111-111111111214','Artículo 132.2 — ¿Qué establece este apartado?','Son bienes de dominio público estatal los que determine la
ley y, en todo caso, la zona marítimo-terrestre, las playas, el
mar territorial y los recursos naturales de la zona económica
y la plataforma continental.', now(), now()),
('d54c9a2e-1bc2-582f-b716-54678858e352','11111111-1111-1111-1111-111111111214','Artículo 132.3 — ¿Qué establece este apartado?','Por ley se regularán el Patrimonio del Estado y el Patrimonio
Nacional, su administración, defensa y conservación.', now(), now()),
('8ced24c2-969b-50c8-97ae-b660a7f1488a','11111111-1111-1111-1111-111111111214','Artículo 133.1 — ¿Qué establece este apartado?','La potestad originaria para establecer los tributos corresponde exclusivamente al Estado, mediante ley.', now(), now()),
('a17e304b-f7ab-5d18-b037-00904c49697b','11111111-1111-1111-1111-111111111214','Artículo 133.2 — ¿Qué establece este apartado?','Las Comunidades Autónomas y las Corporaciones locales
podrán establecer y exigir tributos, de acuerdo con la Constitución y las leyes.', now(), now()),
('62564da4-abe8-5a83-8dd5-be8ce6797caf','11111111-1111-1111-1111-111111111214','Artículo 133.3 — ¿Qué establece este apartado?','Todo beneficio fiscal que afecte a los tributos del Estado
deberá establecerse en virtud de ley.', now(), now()),
('a14e3f76-8013-592a-94e5-6a94413fd1c9','11111111-1111-1111-1111-111111111214','Artículo 133.4 — ¿Qué establece este apartado?','Las administraciones públicas sólo podrán contraer obligaciones financieras y realizar gastos de acuerdo con las leyes.', now(), now()),
('ca96d9c1-4d42-5dc7-9f4e-c115260bba44','11111111-1111-1111-1111-111111111214','Artículo 134.1 — ¿Qué establece este apartado?','Corresponde al Gobierno la elaboración de los Presupuestos Generales del Estado y a las Cortes Generales, su examen, enmienda y aprobación.', now(), now()),
('ac34b49c-a12f-5620-816e-f1eb75e5d234','11111111-1111-1111-1111-111111111214','Artículo 134.2 — ¿Qué establece este apartado?','Los Presupuestos Generales del Estado tendrán carácter
anual, incluirán la totalidad de los gastos e ingresos del
sector público estatal y en ellos se consignará el importe
de los beneficios fiscales que afecten a los tributos del
Estado.', now(), now()),
('8396b6e6-1248-5d50-a0ec-6fba272026c7','11111111-1111-1111-1111-111111111214','Artículo 134.3 — ¿Qué establece este apartado?','El Gobierno deberá presentar ante el Congreso de los
Diputados los Presupuestos Generales del Estado al
menos tres meses antes de la expiración de los del año
anterior.', now(), now()),
('36ac357f-e0b8-50f8-aa1d-184da2323d5a','11111111-1111-1111-1111-111111111214','Artículo 134.4 — ¿Qué establece este apartado?','Si la Ley de Presupuestos no se aprobara antes del primer
día del ejercicio económico correspondiente, se considerarán automáticamente prorrogados los Presupuestos del
ejercicio anterior hasta la aprobación de los nuevos.', now(), now()),
('d0ea85e6-4300-53c1-add2-f35606c59f00','11111111-1111-1111-1111-111111111214','Artículo 134.5 — ¿Qué establece este apartado?','Aprobados los Presupuestos Generales del Estado, el
Gobierno podrá presentar proyectos de ley que impliquen aumento del gasto público o disminución de los
ingresos correspondientes al mismo ejercicio presupuestario.', now(), now()),
('eac93da6-ba60-54be-8e0d-4d0c54f490e4','11111111-1111-1111-1111-111111111214','Artículo 134.6 — ¿Qué establece este apartado?','Toda proposición o enmienda que suponga aumento de
los créditos o disminución de los ingresos presupuestarios
requerirá la conformidad del Gobierno para su tramitación.', now(), now()),
('a669b8c6-4763-508f-872b-014e217b206d','11111111-1111-1111-1111-111111111214','Artículo 134.7 — ¿Qué establece este apartado?','La Ley de Presupuestos no puede crear tributos. Podrá
modificarlos cuando una ley tributaria sustantiva así lo prevea.', now(), now()),
('9fc63827-4bfb-5703-a5dd-cc542c7f30a1','11111111-1111-1111-1111-111111111214','Artículo 135.1 — ¿Qué establece este apartado?','Todas las Administraciones Públicas adecuarán sus actuaciones al principio de estabilidad presupuestaria.', now(), now()),
('c302a0fd-3887-58aa-9cb7-e40ad074c034','11111111-1111-1111-1111-111111111214','Artículo 135.2 — ¿Qué establece este apartado?','El Estado y las Comunidades Autónomas no podrán incurrir
en un déficit estructural que supere los márgenes establecidos, en su caso, por la Unión Europea para sus Estados
Miembros.
Una ley orgánica fijará el déficit estructural máximo permitido al Estado y a las Comunidades Autónomas, en relación
con su producto interior bruto. Las Entidades Locales deberán presentar equilibrio presupuestario.', now(), now()),
('d255c5e3-44cd-5d5c-8e30-353edd9d3f09','11111111-1111-1111-1111-111111111214','Artículo 135.3 — ¿Qué establece este apartado?','El Estado y las Comunidades Autónomas habrán de estar
autorizados por ley para emitir deuda pública o contraer
crédito.
Los créditos para satisfacer los intereses y el capital de la
deuda pública de las Administraciones se entenderán siempre incluidos en el estado de gastos de sus presupuestos y
su pago gozará de prioridad absoluta. Estos créditos no
podrán ser objeto de enmienda o modificación, mientras se
ajusten a las condiciones de la ley de emisión.
El volumen de deuda pública del conjunto de las Administraciones Públicas en relación con el producto interior
bruto del Estado no podrá superar el valor de referencia
establecido en el Tratado de Funcionamiento de la Unión
Europea.', now(), now()),
('f6672780-0ac8-5232-ac55-10b8fbca45f1','11111111-1111-1111-1111-111111111214','Artículo 135.4 — ¿Qué establece este apartado?','Los límites de déficit estructural y de volumen de deuda
pública sólo podrán superarse en caso de catástrofes naturales, recesión económica o situaciones de emergencia
extraordinaria que escapen al control del Estado y perjudiquen considerablemente la situación financiera o la sostenibilidad económica o social del Estado, apreciadas por la
mayoría absoluta de los miembros del Congreso de los
Diputados.', now(), now()),
('b41f0475-f418-5d77-b0f7-94dc9df1d366','11111111-1111-1111-1111-111111111214','Artículo 135.5 — ¿Qué establece este apartado?','Una ley orgánica desarrollará los principios a que se refiere
este artículo, así como la participación, en los procedimientos respectivos, de los órganos de coordinación institucional
entre las Administraciones Públicas en materia de política
fiscal y financiera. En todo caso, regulará:
a) La distribución de los límites de déficit y de deuda
entre las distintas Administraciones Públicas, los
supuestos excepcionales de superación de los mismos
y la forma y plazo de corrección de las desviaciones
que sobre uno y otro pudieran producirse.
b) La metodología y el procedimiento para el cálculo del
déficit estructural.
c) La responsabilidad de cada Administración Pública en
caso de incumplimiento de los objetivos de estabilidad
presupuestaria.', now(), now()),
('f55b49c4-a25b-5ad7-acaf-1b41b12f5c1c','11111111-1111-1111-1111-111111111214','Artículo 135.6 — ¿Qué establece este apartado?','Las Comunidades Autónomas, de acuerdo con sus respectivos Estatutos y dentro de los límites a que se refiere este
artículo, adoptarán las disposiciones que procedan para la
aplicación efectiva del principio de estabilidad en sus normas y decisiones presupuestarias.', now(), now()),
('3d453881-c912-5e2a-b45b-3e9d43de04c6','11111111-1111-1111-1111-111111111214','Artículo 136.1 — ¿Qué establece este apartado?','El Tribunal de Cuentas es el supremo órgano fiscalizador de
las cuentas y de la gestión económica de Estado, así como
del sector público.
Dependerá directamente de las Cortes Generales y ejercerá
sus funciones por delegación de ellas en el examen y comprobación de la Cuenta General del Estado.', now(), now()),
('54462342-775d-5b94-b9a3-7d7c5963ecfe','11111111-1111-1111-1111-111111111214','Artículo 136.2 — ¿Qué establece este apartado?','Las cuentas del Estado y del sector público estatal se rendirán al Tribunal de Cuentas y serán censuradas por éste.
El Tribunal de Cuentas, sin perjuicio de su propia jurisdicción, remitirá a las Cortes Generales un informe anual en el
que, cuando proceda, comunicará las infracciones o responsabilidades en que, a su juicio, se hubiere incurrido.', now(), now()),
('43a209d2-9ddb-5066-9c6b-1220eb313335','11111111-1111-1111-1111-111111111214','Artículo 136.3 — ¿Qué establece este apartado?','Los miembros del Tribunal de Cuentas gozarán de la misma
independencia e inamovilidad y estarán sometidos a las mismas incompatibilidades que los Jueces.', now(), now()),
('f424c4f0-c739-51f3-b8a9-35a8fb3b947c','11111111-1111-1111-1111-111111111214','Artículo 136.4 — ¿Qué establece este apartado?','Una ley orgánica regulará la composición, organización y
funciones del Tribunal de Cuentas.
TÍTULO VIII
De la Organización Territorial del Estado
CAPÍTULO PRIMERO
pRincipios geneRales', now(), now()),
('6556dc74-cbbf-54ce-b21f-fddc0cf2c357','11111111-1111-1111-1111-111111111214','Artículo 137 — ¿Qué establece?','El Estado se organiza territorialmente en municipios, en provincias y en las Comunidades Autónomas que se constituyan. Todas
estas entidades gozan de autonomía para la gestión de sus respectivos intereses.', now(), now()),
('55aeb45c-5c74-53e5-899b-9aef7b83a28b','11111111-1111-1111-1111-111111111214','Artículo 138.1 — ¿Qué establece este apartado?','El Estado garantiza la realización efectiva del principio de
solidaridad consagrado en el artículo 2 de la Constitución,
velando por el establecimiento de un equilibrio económico,
adecuado y justo entre las diversas partes del territorio
español, y atendiendo en particular a las circunstancias del
hecho insular.', now(), now()),
('e9aab87c-702d-58b7-84f3-aebf46284602','11111111-1111-1111-1111-111111111214','Artículo 138.2 — ¿Qué establece este apartado?','Las diferencias entre los Estatutos de las distintas Comunidades Autónomas no podrán implicar, en ningún caso, privilegios económicos o sociales.', now(), now()),
('247de3cf-1e1d-555a-9a01-1328f943cafa','11111111-1111-1111-1111-111111111214','Artículo 139.1 — ¿Qué establece este apartado?','Todos los españoles tienen los mismos derechos y obligaciones en cualquier parte del territorio del Estado.', now(), now()),
('67fb0c1d-6dce-5b0c-ad67-b886e26a7fb1','11111111-1111-1111-1111-111111111214','Artículo 139.2 — ¿Qué establece este apartado?','Ninguna autoridad podrá adoptar medidas que directa o
indirectamente obstaculicen la libertad de circulación y establecimiento de las personas y la libre circulación de bienes
en todo el territorio español.
CAPÍTULO SEGUNDO
de la administRación local', now(), now()),
('1f8a6575-c2e3-5104-9dad-2afef25fa63c','11111111-1111-1111-1111-111111111214','Artículo 140 — ¿Qué establece?','La Constitución garantiza la autonomía de los municipios. Estos
gozarán de personalidad jurídica plena. Su gobierno y administración corresponde a sus respectivos Ayuntamientos, integrados por los Alcaldes y los Concejales. Los Concejales serán
elegidos por los vecinos del municipio mediante sufragio universal, igual, libre, directo y secreto, en la forma establecida por la
ley. Los Alcaldes serán elegidos por los Concejales o por los
vecinos. La ley regulará las condiciones en las que proceda el
régimen del concejo abierto.', now(), now()),
('dcdfcc9d-bcdf-589a-9614-24340ebd909a','11111111-1111-1111-1111-111111111214','Artículo 141.1 — ¿Qué establece este apartado?','La provincia es una entidad local con personalidad jurídica
propia, determinada por la agrupación de municipios y división territorial para el cumplimiento de las actividades del
Estado. Cualquier alteración de los límites provinciales
habrá de ser aprobada por las Cortes Generales mediante
ley orgánica.', now(), now()),
('2fdb9610-cce7-5308-8408-c471dbeb3dd3','11111111-1111-1111-1111-111111111214','Artículo 141.2 — ¿Qué establece este apartado?','El Gobierno y la administración autónoma de las provincias
estarán encomendados a Diputaciones u otras Corporaciones de carácter representativo.', now(), now()),
('90a21475-f106-5502-b74b-f1cff16a301e','11111111-1111-1111-1111-111111111214','Artículo 141.3 — ¿Qué establece este apartado?','Se podrán crear agrupaciones de municipios diferentes de
la provincia.', now(), now()),
('e17856d3-2489-5ab3-a73a-549a28aa4552','11111111-1111-1111-1111-111111111214','Artículo 141.4 — ¿Qué establece este apartado?','En los archipiélagos, las islas tendrán además su administración propia en forma de Cabildos o Consejos.', now(), now()),
('d8388e60-1291-5e15-a4f0-59b8e2e8595e','11111111-1111-1111-1111-111111111214','Artículo 142 — ¿Qué establece?','Las Haciendas locales deberán disponer de los medios suficientes para el desempeño de las funciones que la ley atribuye a las
Corporaciones respectivas y se nutrirán fundamentalmente de
tributos propios y de participación en los del Estado y de las
Comunidades Autónomas.
CAPÍTULO TERCERO
de las comunidades autónomas', now(), now()),
('1f6cd740-6df0-552f-98f7-27055c291fba','11111111-1111-1111-1111-111111111214','Artículo 143.1 — ¿Qué establece este apartado?','En el ejercicio del derecho a la autonomía reconocido en el
artículo 2 de la Constitución, las provincias limítrofes con
características históricas, culturales y económicas comunes,
los territorios insulares y las provincias con entidad regional
histórica podrán acceder a su autogobierno y constituirse en
Comunidades Autónomas con arreglo a lo previsto en este
Título y en los respectivos Estatutos.', now(), now()),
('7257787a-9329-5854-86ba-8f028fa27dd3','11111111-1111-1111-1111-111111111214','Artículo 143.2 — ¿Qué establece este apartado?','La iniciativa del proceso autonómico corresponde a todas las
Diputaciones interesadas o al órgano interinsular correspondiente y a las dos terceras partes de los municipios cuya población represente, al menos, la mayoría del censo electoral de
cada provincia o isla. Estos requisitos deberán ser cumplidos en
el plazo de seis meses desde el primer acuerdo adoptado al
respecto por alguna de las Corporaciones locales interesadas.', now(), now()),
('e7abff5c-5b0d-5f44-9f22-83eaf0579a42','11111111-1111-1111-1111-111111111214','Artículo 143.3 — ¿Qué establece este apartado?','La iniciativa, en caso de no prosperar, solamente podrá reiterarse pasados cinco años.', now(), now()),
('83575552-d526-561b-97f8-1577ab316f05','11111111-1111-1111-1111-111111111214','Artículo 144 — ¿Qué establece?','Las Cortes Generales, mediante ley orgánica, podrán, por motivos de interés nacional:
a) Autorizar la constitución de una comunidad autónoma
cuando su ámbito territorial no supere el de una provincia
y no reúna las condiciones del apartado 1 del artículo 143.
b) Autorizar o acordar, en su caso, un Estatuto de autonomía para territorios que no estén integrados en la organización provincial.
c) Sustituir la iniciativa de las Corporaciones locales a que
se refiere el apartado 2 del artículo 143.', now(), now()),
('1fb1085b-8fb9-52fa-9663-392c5940bca5','11111111-1111-1111-1111-111111111214','Artículo 145.1 — ¿Qué establece este apartado?','En ningún caso se admitirá la federación de Comunidades
Autónomas.', now(), now()),
('e5e18fac-2c18-5aae-ade9-6834d2153ebf','11111111-1111-1111-1111-111111111214','Artículo 145.2 — ¿Qué establece este apartado?','Los Estatutos podrán prever los supuestos, requisitos y términos en que las Comunidades Autónomas podrán celebrar
convenios entre sí para la gestión y prestación de servicios
propios de las mismas, así como el carácter y efectos de la
correspondiente comunicación a las Cortes Generales. En
los demás supuestos, los acuerdos de cooperación entre las
Comunidades Autónomas necesitarán la autorización de las
Cortes Generales.', now(), now()),
('bede3145-4358-50ac-92fc-901d210472a2','11111111-1111-1111-1111-111111111214','Artículo 146 — ¿Qué establece?','El proyecto de Estatuto será elaborado por una asamblea compuesta por los miembros de la Diputación u órgano interinsular
de las provincias afectadas y por los Diputados y Senadores elegidos en ellas y será elevado a las Cortes Generales para su
tramitación como ley.', now(), now()),
('6da1a8f1-4d1f-58db-9931-3f5c2ed6a3ab','11111111-1111-1111-1111-111111111214','Artículo 147.1 — ¿Qué establece este apartado?','Dentro de los términos de la presente Constitución, los
Estatutos serán la norma institucional básica de cada Comunidad Autónoma y el Estado los reconocerá y amparará
como parte integrante de su ordenamiento jurídico.', now(), now()),
('088c8fd3-ffd6-5e5d-9a30-7cbc619d4943','11111111-1111-1111-1111-111111111214','Artículo 147.2 — ¿Qué establece este apartado?','Los Estatutos de autonomía deberán contener:
a) La denominación de la Comunidad que mejor corresponda a su identidad histórica.
b) La delimitación de su territorio.
c) La denominación, organización y sede de las instituciones autónomas propias.
d) Las competencias asumidas dentro del marco establecido en la Constitución y las bases para el traspaso de
los servicios correspondientes a las mismas.', now(), now()),
('845ee28e-404b-5ef6-b046-d3647f3174af','11111111-1111-1111-1111-111111111214','Artículo 147.3 — ¿Qué establece este apartado?','La reforma de los Estatutos se ajustará al procedimiento
establecido en los mismos y requerirá, en todo caso, la aprobación por las Cortes Generales, mediante ley orgánica.', now(), now()),
('6ec493a5-2d0c-5b2b-bb06-8cec3c0ebdb8','11111111-1111-1111-1111-111111111214','Artículo 148.1 — ¿Qué establece este apartado?','Las Comunidades Autónomas podrán asumir competencias
en las siguientes materias:', now(), now()),
('08553cc1-a0d0-5b3a-9a68-0ef9dfee2526','11111111-1111-1111-1111-111111111214','Artículo 148.1 — ¿Qué establece este apartado?','ª Organización de sus instituciones de autogobierno.', now(), now()),
('28f2b277-fa54-5727-a09a-4b2241602636','11111111-1111-1111-1111-111111111214','Artículo 148.2 — ¿Qué establece este apartado?','ª Las alteraciones de los términos municipales comprendidos en su territorio y, en general, las funciones que
correspondan a la Administración del Estado sobre las
Corporaciones locales y cuya transferencia autorice la
legislación sobre Régimen Local.', now(), now()),
('dcd7c469-cd7f-599d-accb-b2c6861ad390','11111111-1111-1111-1111-111111111214','Artículo 148.3 — ¿Qué establece este apartado?','ª Ordenación del territorio, urbanismo y vivienda.', now(), now()),
('5e39c125-01e8-5f94-b9fa-08a61c70c793','11111111-1111-1111-1111-111111111214','Artículo 148.4 — ¿Qué establece este apartado?','ª Las obras públicas de interés de la Comunidad Autónoma en su propio territorio.', now(), now()),
('472c16be-5405-5413-bd50-d938f87bd98b','11111111-1111-1111-1111-111111111214','Artículo 148.5 — ¿Qué establece este apartado?','ª Los ferrocarriles y carreteras cuyo itinerario se desarr olle íntegramente en el territorio de la Comunidad Autónoma y, en los mismos términos, el transporte
desarrollado por estos medios o por cable.', now(), now()),
('a2876ade-1f74-5d4b-aee5-26b9cd61c0fc','11111111-1111-1111-1111-111111111214','Artículo 148.6 — ¿Qué establece este apartado?','ª Los puertos de refugio, los puertos y aeropuertos
deportivos y, en general, los que no desarrollen actividades comerciales.', now(), now()),
('5e18299d-b1da-5aea-89c0-d4aaefdaa379','11111111-1111-1111-1111-111111111214','Artículo 148.7 — ¿Qué establece este apartado?','ª La agricultura y ganadería, de acuerdo con la ordenación general de la economía.', now(), now()),
('a9745677-5b2a-5f53-8cb8-7b06deb74636','11111111-1111-1111-1111-111111111214','Artículo 148.8 — ¿Qué establece este apartado?','ª Los montes y aprovechamientos forestales.', now(), now()),
('1ab8d66d-ea52-5bd9-b38c-9c8e22fe5db6','11111111-1111-1111-1111-111111111214','Artículo 148.9 — ¿Qué establece este apartado?','ª La gestión en materia de protección del medio ambiente.', now(), now()),
('9b2a56aa-b283-56c0-a08d-86ca27096bcd','11111111-1111-1111-1111-111111111214','Artículo 148.10 — ¿Qué establece este apartado?','ª Los proyectos, construcción y explotación de los aprovechamientos hidráulicos, canales y regadíos de interés de
la Comunidad Autónoma; las aguas minerales y termales.', now(), now()),
('4f627bae-3ee6-5dbf-b0d5-d99c293b91f2','11111111-1111-1111-1111-111111111214','Artículo 148.11 — ¿Qué establece este apartado?','ª La pesca en aguas interiores, el marisqueo y la acuicultura, la caza y la pesca fluvial.', now(), now()),
('01bcd2a7-df8e-553e-9ad9-70b9b5b68645','11111111-1111-1111-1111-111111111214','Artículo 148.12 — ¿Qué establece este apartado?','ª Ferias interiores.', now(), now()),
('44b2c525-89dc-5426-9d43-c30aa5ffcaee','11111111-1111-1111-1111-111111111214','Artículo 148.13 — ¿Qué establece este apartado?','ª El fomento del desarrollo económico de la Comunidad
Autónoma dentro de los objetivos marcados por la
política económica nacional.', now(), now()),
('ddd47815-14cc-52be-a53d-d254c1edb7f6','11111111-1111-1111-1111-111111111214','Artículo 148.14 — ¿Qué establece este apartado?','ª La artesanía.', now(), now()),
('39071a38-1f0d-56d9-ad7f-5392c11bec3c','11111111-1111-1111-1111-111111111214','Artículo 148.15 — ¿Qué establece este apartado?','ª Museos, bibliotecas y conservatorios de música de interés para la Comunidad Autónoma.', now(), now()),
('f768e15c-2423-5f0b-9fc6-047ebbf0a8e5','11111111-1111-1111-1111-111111111214','Artículo 148.16 — ¿Qué establece este apartado?','ª Patrimonio monumental de interés de la Comunidad
Autónoma.', now(), now()),
('f74ba0b8-6f98-56f4-9d47-247633629e2a','11111111-1111-1111-1111-111111111214','Artículo 148.17 — ¿Qué establece este apartado?','ª El fomento de la cultura, de la investigación y, en su
caso, de la enseñanza de la lengua de la Comunidad
Autónoma.', now(), now()),
('88ecba80-9b82-504a-abda-f1d776302e94','11111111-1111-1111-1111-111111111214','Artículo 148.18 — ¿Qué establece este apartado?','ª Promoción y ordenación del turismo en su ámbito territorial.', now(), now()),
('23c5c3ee-e960-586a-9704-1e736f43cc34','11111111-1111-1111-1111-111111111214','Artículo 148.19 — ¿Qué establece este apartado?','ª Promoción del deporte y de la adecuada utilización del
ocio.', now(), now()),
('fd86052e-38e8-5beb-aa84-7c3c1db9b609','11111111-1111-1111-1111-111111111214','Artículo 148.20 — ¿Qué establece este apartado?','ª Asistencia social.', now(), now()),
('a88a78e0-e5dd-55f5-bef8-34638f02d58f','11111111-1111-1111-1111-111111111214','Artículo 148.21 — ¿Qué establece este apartado?','ª Sanidad e higiene.', now(), now()),
('471d0dae-11e8-563e-8995-3e6f473ebee6','11111111-1111-1111-1111-111111111214','Artículo 148.22 — ¿Qué establece este apartado?','ª La vigilancia y protección de sus edificios e instalaciones. La coordinación y demás facultades en relación
con las policías locales en los términos que establezca
una ley orgánica.', now(), now()),
('f980d8f9-94d5-5747-9606-119e43e2397e','11111111-1111-1111-1111-111111111214','Artículo 148.2 — ¿Qué establece este apartado?','Transcurridos cinco años, y mediante la reforma de sus Estatutos, las Comunidades Autónomas podrán ampliar sucesivamente sus competencias dentro del marco establecido en
el artículo 149.', now(), now()),
('f7200dab-6e5f-51d7-9a4f-78a64c07d483','11111111-1111-1111-1111-111111111214','Artículo 149.1 — ¿Qué establece este apartado?','El Estado tiene competencia exclusiva sobre las siguientes
materias:', now(), now()),
('e01cd056-7bdf-579e-81c9-3c91e023b0c6','11111111-1111-1111-1111-111111111214','Artículo 149.1 — ¿Qué establece este apartado?','ª La regulación de las condiciones básicas que garanticen
la igualdad de todos los españoles en el ejercicio de los
derechos y en el cumplimiento de los deberes constitucionales.', now(), now()),
('4fc3720b-2cae-5baf-9466-763cdf325f28','11111111-1111-1111-1111-111111111214','Artículo 149.2 — ¿Qué establece este apartado?','ª Nacionalidad, inmigración, emigración, extranjería y
derecho de asilo.', now(), now()),
('2660c192-d248-593b-aa2a-910575ff9232','11111111-1111-1111-1111-111111111214','Artículo 149.3 — ¿Qué establece este apartado?','ª Relaciones internacionales.', now(), now()),
('0955cd4a-f821-5346-b6d1-b3629bd1a4c2','11111111-1111-1111-1111-111111111214','Artículo 149.4 — ¿Qué establece este apartado?','ª Defensa y Fuerzas Armadas.', now(), now()),
('3cf0234b-1651-511f-82b4-e08a1aa9235c','11111111-1111-1111-1111-111111111214','Artículo 149.5 — ¿Qué establece este apartado?','ª Administración de Justicia.', now(), now()),
('308094c5-3448-5aa6-87cf-15000ab7ece7','11111111-1111-1111-1111-111111111214','Artículo 149.6 — ¿Qué establece este apartado?','ª Legislación mercantil, penal y penitenciaria; legislación
procesal, sin perjuicio de las necesarias especialidades
que en este orden se deriven de las particularidades del
derecho sustantivo de las Comunidades Autónomas.', now(), now()),
('ba724a49-e526-5a78-b15f-c6e88415c11d','11111111-1111-1111-1111-111111111214','Artículo 149.7 — ¿Qué establece este apartado?','ª Legislación laboral; sin perjuicio de su ejecución por los
órganos de las Comunidades Autónomas.', now(), now()),
('513ae19d-efdd-5e52-9c08-6dc08b87fdb5','11111111-1111-1111-1111-111111111214','Artículo 149.8 — ¿Qué establece este apartado?','ª Legislación civil, sin perjuicio de la conservación, modificación y desarrollo por las Comunidades Autónomas
de los derechos civiles, forales o especiales, allí donde
existan. En todo caso, las reglas relativas a la aplicación
y eficacia de las normas jurídicas, relaciones jurídicociviles relativas a las formas de matrimonio, ordenación
de los registros e instrumentos públicos, bases de las
obligaciones contractuales, normas para resolver los
conflictos de leyes y determinación de las fuentes del
Derecho, con respeto, en este último caso, a las normas
de derecho foral o especial.', now(), now()),
('52aa4b4a-cd50-5aa7-9f44-05df9426d002','11111111-1111-1111-1111-111111111214','Artículo 149.9 — ¿Qué establece este apartado?','ª Legislación sobre propiedad intelectual e industrial.', now(), now()),
('b3017945-3e00-5b82-a97e-b29db2bdcf5e','11111111-1111-1111-1111-111111111214','Artículo 149.10 — ¿Qué establece este apartado?','ª Régimen aduanero y arancelario; comercio exterior .', now(), now()),
('7ccd71ab-f5ef-5b18-a8e1-1f11414fb8e8','11111111-1111-1111-1111-111111111214','Artículo 149.11 — ¿Qué establece este apartado?','ª Sistema monetario: divisas, cambio y convertibilidad;
bases de la ordenación de crédito, banca y seguros.', now(), now()),
('783a7d51-cab2-5f27-8870-671a047f19aa','11111111-1111-1111-1111-111111111214','Artículo 149.12 — ¿Qué establece este apartado?','ª Legislación sobre pesas y medidas, determinación de la
hora oficial.', now(), now()),
('8c66c700-1962-507a-a40b-fea3ec256e80','11111111-1111-1111-1111-111111111214','Artículo 149.13 — ¿Qué establece este apartado?','ª Bases y coordinación de la planificación general de la
actividad económica.', now(), now()),
('2a218f0b-0d35-57b5-96df-2f9f0a0bfb64','11111111-1111-1111-1111-111111111214','Artículo 149.14 — ¿Qué establece este apartado?','ª Hacienda general y Deuda del Estado.', now(), now()),
('249f46b9-a1af-538e-a769-c5b0ef7d9aea','11111111-1111-1111-1111-111111111214','Artículo 149.15 — ¿Qué establece este apartado?','ª Fomento y coordinación general de la investigación
científica y técnica.', now(), now()),
('ea6dc349-27a0-5ebc-a4bc-283a5a754444','11111111-1111-1111-1111-111111111214','Artículo 149.16 — ¿Qué establece este apartado?','ª Sanidad exterior. Bases y coordinación general de la
sanidad. Legislación sobre productos farmacéuticos.', now(), now()),
('669c458e-9db3-51a3-a460-3ff3031be9df','11111111-1111-1111-1111-111111111214','Artículo 149.17 — ¿Qué establece este apartado?','ª Legislación básica y régimen económico de la Seguridad Social, sin perjuicio de la ejecución de sus servicios
por las Comunidades Autónomas.', now(), now()),
('d71f3391-f76f-5b96-b567-a26bcdb4e812','11111111-1111-1111-1111-111111111214','Artículo 149.18 — ¿Qué establece este apartado?','ª Las bases del régimen jurídico de las Administraciones
públicas y del régimen estatutario de sus funcionarios
que, en todo caso, garantizarán a los administrados un
tratamiento común ante ellas; el procedimiento administrativo común, sin perjuicio de las especialidades
derivadas de la organización propia de las Comunidades Autónomas; legislación sobre expropiación forzosa; legislación básica sobre contratos y concesiones
administrativas y el sistema de responsabilidad de
todas las Administraciones públicas.', now(), now()),
('145313a4-bf20-5cdb-b520-8f419c99c213','11111111-1111-1111-1111-111111111214','Artículo 149.19 — ¿Qué establece este apartado?','ª Pesca marítima, sin perjuicio de las competencias que
en la ordenación del sector se atribuyan a las Comunidades Autónomas.', now(), now()),
('c0b4233e-f4cb-5d07-8579-4c648125b765','11111111-1111-1111-1111-111111111214','Artículo 149.20 — ¿Qué establece este apartado?','ª Marina mercante y abanderamiento de buques; iluminación de costas y señales marítimas; puertos de interés general; aeropuertos de interés general; control del
espacio aéreo, tránsito y transporte aéreo, servicio
meteorológico y matriculación de aeronaves.', now(), now()),
('ab10d570-8111-5883-8167-9fc8528579ac','11111111-1111-1111-1111-111111111214','Artículo 149.21 — ¿Qué establece este apartado?','ª Ferrocarriles y transportes terrestres que transcurran
por el territorio de más de una Comunidad Autónoma;
régimen general de comunicaciones; tráfico y circulación de vehículos a motor; correos y telecomunicaciones; cables aéreos, submarinos y radiocomunicación.', now(), now()),
('b2f7406c-349b-5647-967c-e30ba8f3ed88','11111111-1111-1111-1111-111111111214','Artículo 149.22 — ¿Qué establece este apartado?','ª La legislación, ordenación y concesión de recursos y
aprovechamientos hidráulicos cuando las aguas discurran por más de una Comunidad Autónoma, y la autorización de las instalaciones eléctricas cuando su
aprovechamiento afecte a otra Comunidad o el transporte de energía salga de su ámbito territorial.', now(), now()),
('f7097f0b-1cb0-5fe7-96e0-02fc8c871d25','11111111-1111-1111-1111-111111111214','Artículo 149.23 — ¿Qué establece este apartado?','ª Legislación básica sobre protección del medio
ambiente, sin perjuicio de las facultades de las Comunidades Autónomas de establecer normas adicionales
de protección. La legislación básica sobre montes,
aprovechamientos forestales y vías pecuarias.', now(), now()),
('84723e14-a1cf-5775-8c9b-941d3e9cf13e','11111111-1111-1111-1111-111111111214','Artículo 149.24 — ¿Qué establece este apartado?','ª Obras públicas de interés general o cuya realización
afecte a más de una Comunidad Autónoma.', now(), now()),
('449aad61-d365-5559-9357-6a4049b4c10a','11111111-1111-1111-1111-111111111214','Artículo 149.25 — ¿Qué establece este apartado?','ª Bases de régimen minero y ener gético.', now(), now()),
('6afcd7ed-1ff1-5dd3-9a12-dd20a759c780','11111111-1111-1111-1111-111111111214','Artículo 149.26 — ¿Qué establece este apartado?','ª Régimen de producción, comercio, tenencia y uso de
armas y explosivos.', now(), now()),
('c16792b3-7bb6-59a2-bb43-64c8426648c8','11111111-1111-1111-1111-111111111214','Artículo 149.27 — ¿Qué establece este apartado?','ª Normas básicas del régimen de prensa, radio y televisión y, en general, de todos los medios de comunicación social, sin perjuicio de las facultades que en su
desarrollo y ejecución correspondan a las Comunidades
Autónomas.', now(), now()),
('6830c30e-12ef-577c-a1b9-b2f778ef12dd','11111111-1111-1111-1111-111111111214','Artículo 149.28 — ¿Qué establece este apartado?','ª Defensa del patrimonio cultural, artístico y monumental
español contra la exportación y la expoliación; museos,
bibliotecas y archivos de titularidad estatal, sin perjuicio
de su gestión por parte de las Comunidades Autónomas.', now(), now()),
('a38534a2-ce3b-51b9-a7c3-0b006d7f3a0c','11111111-1111-1111-1111-111111111214','Artículo 149.29 — ¿Qué establece este apartado?','ª Seguridad pública, sin perjuicio de la posibilidad de
creación de policías por las Comunidades Autónomas
en la forma que se establezca en los respectivos Estatutos en el marco de lo que disponga una ley orgánica.', now(), now()),
('9acb8ead-b6a7-5a30-a0d9-39e3e5638f71','11111111-1111-1111-1111-111111111214','Artículo 149.30 — ¿Qué establece este apartado?','ª Regulación de las condiciones de obtención, expedición
y homologación de títulos académicos y profesionales y
normas básicas para el desarrollo del artículo 27 de la
Constitución, a fin de garantizar el cumplimiento de las
obligaciones de los poderes públicos en esta materia.', now(), now()),
('b3542c36-dd0f-5cbd-92ed-e228ccb834b3','11111111-1111-1111-1111-111111111214','Artículo 149.31 — ¿Qué establece este apartado?','ª Estadística para fines estatales.', now(), now()),
('e3d5f405-974e-505a-ac28-a8e7aa61d005','11111111-1111-1111-1111-111111111214','Artículo 149.32 — ¿Qué establece este apartado?','ª Autorización para la convocatoria de consultas populares por vía de referéndum.', now(), now()),
('b100ca37-eb3d-5f8a-aed9-9755cd7afab7','11111111-1111-1111-1111-111111111214','Artículo 149.2 — ¿Qué establece este apartado?','Sin perjuicio de las competencias que podrán asumir las
Comunidades Autónomas, el Estado considerará el servicio
de la cultura como deber y atribución esencial y facilitará la
comunicación cultural entre las Comunidades Autónomas,
de acuerdo con ellas.', now(), now()),
('d817bc08-043d-5f21-b1d1-04128129886a','11111111-1111-1111-1111-111111111214','Artículo 149.3 — ¿Qué establece este apartado?','Las materias no atribuidas expresamente al Estado por esta
Constitución podrán corresponder a las Comunidades Autónomas, en virtud de sus respectivos Estatutos. La competencia sobre las materias que no se hayan asumido por los
Estatutos de Autonomía corresponderá al Estado, cuyas
normas prevalecerán, en caso de conflicto, sobre las de las
Comunidades Autónomas en todo lo que no esté atribuido
a la exclusiva competencia de éstas. El derecho estatal será,
en todo caso, supletorio del derecho de las Comunidades
Autónomas.', now(), now()),
('1ea17d05-1eed-51ec-b92f-12a7d26a9995','11111111-1111-1111-1111-111111111214','Artículo 150.1 — ¿Qué establece este apartado?','Las Cortes Generales, en materias de competencia estatal,
podrán atribuir a todas o a alguna de las Comunidades
Autónomas la facultad de dictar, para sí mismas, normas
legislativas en el marco de los principios, bases y directrices
fijados por una ley estatal. Sin perjuicio de la competencia
de los Tribunales, en cada ley marco se establecerá la modalidad del control de las Cortes Generales sobre estas normas legislativas de las Comunidades Autónomas.', now(), now()),
('c069b7c7-f00a-5801-83a5-a8d2fe1c72b1','11111111-1111-1111-1111-111111111214','Artículo 150.2 — ¿Qué establece este apartado?','El Estado podrá transferir o delegar en las Comunidades
Autónomas, mediante ley orgánica, facultades correspondientes a materia de titularidad estatal que por su propia
naturaleza sean susceptibles de transferencia o delegación.
La ley preverá en cada caso la correspondiente transferencia
de medios financieros, así como las formas de control que
se reserve el Estado.', now(), now()),
('413e1ab4-837f-5a7a-a89b-1319a387a6d4','11111111-1111-1111-1111-111111111214','Artículo 150.3 — ¿Qué establece este apartado?','El Estado podrá dictar leyes que establezcan los principios
necesarios para armonizar las disposiciones normativas de
las Comunidades Autónomas, aun en el caso de materias
atribuidas a la competencia de éstas, cuando así lo exija el
interés general. Corresponde a las Cortes Generales, por
mayoría absoluta de cada Cámara, la apreciación de esta
necesidad.', now(), now()),
('97bc6d96-aa0c-53e6-ad19-8691a0c67854','11111111-1111-1111-1111-111111111214','Artículo 151.1 — ¿Qué establece este apartado?','No será preciso dejar transcurrir el plazo de cinco años, a
que se refiere el apartado 2 del artículo 148, cuando la iniciativa del proceso autonómico sea acordada dentro del
plazo del artículo 143.2, además de por las Diputaciones o
los órganos interinsulares correspondientes, por las tres
cuartas partes de los municipios de cada una de las provincias afectadas que representen, al menos, la mayoría del
censo electoral de cada una de ellas y dicha iniciativa sea
ratificada mediante referéndum por el voto afirmativo de la
mayoría absoluta de los electores de cada provincia en los
términos que establezca una ley orgánica.', now(), now()),
('85283db7-52f0-560d-bf95-076966b1b8d5','11111111-1111-1111-1111-111111111214','Artículo 151.2 — ¿Qué establece este apartado?','En el supuesto previsto en el apartado anterior, el procedimiento para la elaboración del Estatuto será el siguiente:', now(), now()),
('2fdef3b6-5e76-5b0f-b64f-6e2730175cfb','11111111-1111-1111-1111-111111111214','Artículo 151.1 — ¿Qué establece este apartado?','º El Gobierno convocará a todos los Diputados y Senadores elegidos en las circunscripciones comprendidas
en el ámbito territorial que pretenda acceder al autogobierno, para que se constituyan en Asamblea, a los
solos efectos de elaborar el correspondiente proyecto
de Estatuto de autonomía, mediante el acuerdo de la
mayoría absoluta de sus miembros.', now(), now()),
('34789110-b7c8-50d1-afc8-c891d21d39d2','11111111-1111-1111-1111-111111111214','Artículo 151.2 — ¿Qué establece este apartado?','º Aprobado el proyecto de Estatuto por la Asamblea de
Parlamentarios, se remitirá a la Comisión Constitucional
del Congreso, la cual, dentro del plazo de dos meses,
lo examinará con el concurso y asistencia de una delegación de la Asamblea proponente para determinar de
común acuerdo su formulación definitiva.', now(), now()),
('0fed87e6-4741-5c15-ac9e-6df4488f1c98','11111111-1111-1111-1111-111111111214','Artículo 151.3 — ¿Qué establece este apartado?','º Si se alcanzare dicho acuerdo, el texto r esultante será
sometido a referéndum del cuerpo electoral de las provincias comprendidas en el ámbito territorial del proyectado Estatuto.', now(), now()),
('16146de0-3420-5e98-9cd8-564f421f6f48','11111111-1111-1111-1111-111111111214','Artículo 151.4 — ¿Qué establece este apartado?','º Si el proyecto de Estatuto es aprobado en cada provincia por la mayoría de los votos válidamente emitidos,
será elevado a las Cortes Generales. Los plenos de
ambas Cámaras decidirán sobre el texto mediante un
voto de ratificación. Aprobado el Estatuto, el Rey lo
sancionará y lo promulgará como ley.', now(), now()),
('309f6d94-65c3-542c-96fa-e179588aa349','11111111-1111-1111-1111-111111111214','Artículo 151.5 — ¿Qué establece este apartado?','º De no alcanzarse el acuerdo a que se refier e el apartado 2 de este número, el proyecto de Estatuto será
tramitado como proyecto de ley ante las Cortes Generales. El texto aprobado por éstas será sometido a referéndum del cuerpo electoral de las provincias comprendidas
en el ámbito territorial del proyectado Estatuto. En caso
de ser aprobado por la mayoría de los votos válidamente
emitidos en cada provincia, procederá su promulgación
en los términos del párrafo anterior.', now(), now()),
('e3f5acf5-4a16-5478-9826-447e9e0a282b','11111111-1111-1111-1111-111111111214','Artículo 151.3 — ¿Qué establece este apartado?','En los casos de los párrafos 4.º y 5.º del apartado anterior, la
no aprobación del proyecto de Estatuto por una o varias provincias no impedirá la constitución entre las restantes de la
Comunidad Autónoma proyectada, en la forma que establezca
la ley orgánica prevista en el apartado 1 de este artículo.', now(), now()),
('c552e7e7-815b-55bf-a08f-8bbb1f7bf8cb','11111111-1111-1111-1111-111111111214','Artículo 152.1 — ¿Qué establece este apartado?','En los Estatutos aprobados por el procedimiento a que se
refiere el artículo anterior, la organización institucional autonómica se basará en una Asamblea Legislativa, elegida por
sufragio universal, con arreglo a un sistema de representación proporcional que asegure, además, la representación
de las diversas zonas del territorio; un Consejo de Gobierno
con funciones ejecutivas y administrativas y un Presidente,
elegido por la Asamblea, de entre sus miembros, y nombrado por el Rey, al que corresponde la dirección del Consejo de Gobierno, la suprema representación de la
respectiva Comunidad y la ordinaria del Estado en aquélla.
El Presidente y los miembros del Consejo de Gobierno
serán políticamente responsables ante la Asamblea.
Un Tribunal Superior de Justicia, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo, culminará la
organización judicial en el ámbito territorial de la Comunidad Autónoma. En los Estatutos de las Comunidades Autónomas podrán establecerse los supuestos y las formas de
participación de aquéllas en la organización de las demarcaciones judiciales del territorio. Todo ello de conformidad
con lo previsto en la ley orgánica del poder judicial y dentro
de la unidad e independencia de éste.
Sin perjuicio de lo dispuesto en el artículo 123, las sucesivas
instancias procesales, en su caso, se agotarán ante órganos
judiciales radicados en el mismo territorio de la Comunidad
Autónoma en que esté el órgano competente en primera
instancia.', now(), now()),
('0382be27-02b4-55c6-97cc-a185d24e300f','11111111-1111-1111-1111-111111111214','Artículo 152.2 — ¿Qué establece este apartado?','Una vez sancionados y promulgados los respectivos Estatutos, solamente podrán ser modificados mediante los procedimientos en ellos establecidos y con referéndum entre los
electores inscritos en los censos correspondientes.', now(), now()),
('419852fe-6564-56d2-8e97-1a788e6c7f78','11111111-1111-1111-1111-111111111214','Artículo 152.3 — ¿Qué establece este apartado?','Mediante la agrupación de municipios limítrofes, los Estatutos podrán establecer circunscripciones territoriales propias,
que gozarán de plena personalidad jurídica.', now(), now()),
('0b525344-c610-5d35-a776-ed465f4e1351','11111111-1111-1111-1111-111111111214','Artículo 153 — ¿Qué establece?','El control de la actividad de los órganos de las Comunidades
Autónomas se ejercerá:
a) Por el Tribunal Constitucional, el relativo a la constitucionalidad de sus disposiciones normativas con fuerza de ley.
b) Por el Gobierno, previo dictamen del Consejo de
Estado, el del ejercicio de funciones delegadas a que
se refiere el apartado 2 del artículo 150.
c) Por la jurisdicción contencioso-administrativa, el de la
administración autónoma y sus normas reglamentarias.
d) Por el Tribunal de Cuentas, el económico y presupuestario.', now(), now()),
('4938fd05-1253-5959-b9aa-7d8a84d7ece7','11111111-1111-1111-1111-111111111214','Artículo 154 — ¿Qué establece?','Un Delegado nombrado por el Gobierno dirigirá la Administración del Estado en el territorio de la Comunidad Autónoma y la
coordinará, cuando proceda, con la administración propia de la
Comunidad.', now(), now()),
('c82690cf-d952-5cf5-adf7-b2f468a1c332','11111111-1111-1111-1111-111111111214','Artículo 155.1 — ¿Qué establece este apartado?','Si una Comunidad Autónoma no cumpliere las obligaciones
que la Constitución u otras leyes le impongan, o actuare de
forma que atente gravemente al interés general de España,
el Gobierno, previo requerimiento al Presidente de la
Comunidad Autónoma y, en el caso de no ser atendido, con
la aprobación por mayoría absoluta del Senado, podrá
adoptar las medidas necesarias para obligar a aquélla al
cumplimiento forzoso de dichas obligaciones o para la protección del mencionado interés general.', now(), now()),
('a1a4c1f9-886e-5d5e-92f9-8e589e037e4c','11111111-1111-1111-1111-111111111214','Artículo 155.2 — ¿Qué establece este apartado?','Para la ejecución de las medidas previstas en el apartado
anterior, el Gobierno podrá dar instrucciones a todas las
autoridades de las Comunidades Autónomas.', now(), now()),
('beab2863-9761-5eab-8682-d5a5bc8b67e6','11111111-1111-1111-1111-111111111214','Artículo 156.1 — ¿Qué establece este apartado?','Las Comunidades Autónomas gozarán de autonomía financiera para el desarrollo y ejecución de sus competencias con
arreglo a los principios de coordinación con la Hacienda
estatal y de solidaridad entre todos los españoles.', now(), now()),
('5d9d006f-0c3e-5a94-8ed8-a34d8cd673ad','11111111-1111-1111-1111-111111111214','Artículo 156.2 — ¿Qué establece este apartado?','Las Comunidades Autónomas podrán actuar como delegados o colaboradores del Estado para la recaudación, la gestión y la liquidación de los recursos tributarios de aquél, de
acuerdo con las leyes y los Estatutos.', now(), now()),
('52ecc293-3e73-595a-8b44-e8e5bc4ebfa7','11111111-1111-1111-1111-111111111214','Artículo 157.1 — ¿Qué establece este apartado?','Los recursos de las Comunidades Autónomas estarán constituidos por:
a) Impuestos cedidos total o parcialmente por el Estado;
recargos sobre impuestos estatales y otras participaciones en los ingresos del Estado.
b) Sus propios impuestos, tasas y contribuciones especiales.
c) Transferencias de un Fondo de Compensación interterritorial y otras asignaciones con cargo a los Presupuestos Generales del Estado.
d) Rendimientos procedentes de su patrimonio e ingresos
de derecho privado.
e) El producto de las operaciones de crédito.', now(), now()),
('85a96186-37e0-5463-b39e-e52911005105','11111111-1111-1111-1111-111111111214','Artículo 157.2 — ¿Qué establece este apartado?','Las Comunidades Autónomas no podrán en ningún caso
adoptar medidas tributarias sobre bienes situados fuera de
su territorio o que supongan obstáculo para la libre circulación de mercancías o servicios.', now(), now()),
('ae9a0c59-55ba-54bc-8f28-521c01b00134','11111111-1111-1111-1111-111111111214','Artículo 157.3 — ¿Qué establece este apartado?','Mediante ley orgánica podrá regularse el ejercicio de las
competencias financieras enumeradas en el precedente
apartado 1, las normas para resolver los conflictos que
pudieran surgir y las posibles formas de colaboración financiera entre las Comunidades Autónomas y el Estado.', now(), now()),
('a2793407-e1e0-5aa5-94c2-3c72621b6cc1','11111111-1111-1111-1111-111111111214','Artículo 158.1 — ¿Qué establece este apartado?','En los Presupuestos Generales del Estado podrá establecerse una asignación a las Comunidades Autónomas en función del volumen de los servicios y actividades estatales que
hayan asumido y de la garantía de un nivel mínimo en la
prestación de los servicios públicos fundamentales en todo
el territorio español.', now(), now()),
('75b1bbe9-0d8c-5896-a6d7-6ccd2429d877','11111111-1111-1111-1111-111111111214','Artículo 158.2 — ¿Qué establece este apartado?','Con el fin de corregir desequilibrios económicos interterritoriales y hacer efectivo el principio de solidaridad, se constituirá un Fondo de Compensación con destino a gastos de
inversión, cuyos recursos serán distribuidos por las Cortes
Generales entre las Comunidades Autónomas y provincias,
en su caso.
TÍTULO IX
Del Tribunal Constitucional', now(), now()),
('515a738a-f10f-5b26-b3f8-01428206a5f4','11111111-1111-1111-1111-111111111220','Artículo 159.1 — ¿Qué establece este apartado?','El Tribunal Constitucional se compone de 12 miembros
nombrados por el Rey; de ellos, cuatro a propuesta del Congreso por mayoría de tres quintos de sus miembros; cuatro
a propuesta del Senado, con idéntica mayoría; dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial.', now(), now()),
('ba1bd7a7-609a-5d9b-bf34-ba80a8d4522e','11111111-1111-1111-1111-111111111220','Artículo 159.2 — ¿Qué establece este apartado?','Los miembros del Tribunal Constitucional deberán ser nombrados entre Magistrados y Fiscales, Profesores de Universidad, funcionarios públicos y Abogados, todos ellos juristas
de reconocida competencia con más de quince años de
ejercicio profesional.', now(), now()),
('491d7038-8393-5290-ad13-a61c1b1c7037','11111111-1111-1111-1111-111111111220','Artículo 159.3 — ¿Qué establece este apartado?','Los miembros del Tribunal Constitucional serán designados
por un período de nueve años y se renovarán por terceras
partes cada tres.', now(), now()),
('5e8f3d88-f3c4-593b-9633-fe232d5fd8e0','11111111-1111-1111-1111-111111111220','Artículo 159.4 — ¿Qué establece este apartado?','La condición de miembro del Tribunal Constitucional es
incompatible: con todo mandato representativo; con los
cargos políticos o administrativos; con el desempeño de
funciones directivas en un partido político o en un sindicato
y con el empleo al servicio de los mismos; con el ejercicio de
las carreras judicial y fiscal, y con cualquier actividad profesional o mercantil.
En lo demás los miembros del Tribunal Constitucional tendrán las incompatibilidades propias de los miembros del
poder judicial.', now(), now()),
('a35c87e0-bef2-5a8a-b850-4e4ed31fa737','11111111-1111-1111-1111-111111111220','Artículo 159.5 — ¿Qué establece este apartado?','Los miembros del Tribunal Constitucional serán independientes e inamovibles en el ejercicio de su mandato.', now(), now()),
('56360952-76f1-5464-9326-5c257ee21df3','11111111-1111-1111-1111-111111111220','Artículo 160 — ¿Qué establece?','El Presidente del Tribunal Constitucional será nombrado entre
sus miembros por el Rey, a propuesta del mismo Tribunal en
pleno y por un período de tres años.', now(), now()),
('4083ba4a-7d91-54f8-9a8f-e145653c3f29','11111111-1111-1111-1111-111111111220','Artículo 161.1 — ¿Qué establece este apartado?','El Tribunal Constitucional tiene jurisdicción en todo el territorio español y es competente para conocer:
a) Del recurso de inconstitucionalidad contra leyes y disposiciones normativas con fuerza de ley. La declaración
de inconstitucionalidad de una norma jurídica con
rango de ley, interpretada por la jurisprudencia, afectará a ésta, si bien la sentencia o sentencias recaídas no
perderán el valor de cosa juzgada.
b) Del recurso de amparo por violación de los derechos y
libertades referidos en el artículo 53, 2, de esta Constitución, en los casos y formas que la ley establezca.
c) De los conflictos de competencia entre el Estado y las
Comunidades Autónomas o de los de éstas entre sí.
d) De las demás materias que le atribuyan la Constitución
o las leyes orgánicas.', now(), now()),
('1eff71ea-0939-50aa-9537-fe96619ed5cc','11111111-1111-1111-1111-111111111220','Artículo 161.2 — ¿Qué establece este apartado?','El Gobierno podrá impugnar ante el Tribunal Constitucional
las disposiciones y resoluciones adoptadas por los órganos
de las Comunidades Autónomas. La impugnación producirá
la suspensión de la disposición o resolución recurrida, pero
el Tribunal, en su caso, deberá ratificarla o levantarla en un
plazo no superior a cinco meses.', now(), now()),
('51c9db6d-c579-5069-83e7-dad9c4a363e1','11111111-1111-1111-1111-111111111220','Artículo 162.1 — ¿Qué establece este apartado?','Están legitimados:
a) Para interponer el recurso de inconstitucionalidad, el
Presidente del Gobierno, el Defensor del Pueblo, 50
Diputados, 50 Senadores, los órganos colegiados ejecutivos de las Comunidades Autónomas y, en su caso,
las Asambleas de las mismas.
b) Para interponer el recurso de amparo, toda persona
natural o jurídica que invoque un interés legítimo, así
como el Defensor del Pueblo y el Ministerio Fiscal.', now(), now()),
('c7e41124-e85d-536c-9794-f60c86674cff','11111111-1111-1111-1111-111111111220','Artículo 162.2 — ¿Qué establece este apartado?','En los demás casos, la ley orgánica determinará las personas
y órganos legitimados.', now(), now()),
('d9065203-6c96-5158-b1c4-8ffa048f8a8d','11111111-1111-1111-1111-111111111220','Artículo 163 — ¿Qué establece?','Cuando un órgano judicial considere, en algún proceso, que una
norma con rango de ley, aplicable al caso, de cuya validez
dependa el fallo, pueda ser contraria a la Constitución, planteará la cuestión ante el Tribunal Constitucional en los supuestos, en la forma y con los efectos que establezca la ley, que en
ningún caso serán suspensivos.', now(), now()),
('63757ea1-d1c4-5eec-a52e-254938b5ff44','11111111-1111-1111-1111-111111111220','Artículo 164.1 — ¿Qué establece este apartado?','Las sentencias del Tribunal Constitucional se publicarán en
el boletín oficial del Estado con los votos particulares, si los
hubiere. Tienen el valor de cosa juzgada a partir del día
siguiente de su publicación y no cabe recurso alguno contra
ellas. Las que declaren la inconstitucionalidad de una ley o
de una norma con fuerza de ley y todas las que no se limiten
a la estimación subjetiva de un derecho, tienen plenos efectos frente a todos.', now(), now()),
('5c38923c-10b3-591c-b6a5-870b506c6b7f','11111111-1111-1111-1111-111111111220','Artículo 164.2 — ¿Qué establece este apartado?','Salvo que en el fallo se disponga otra cosa, subsistirá la
vigencia de la ley en la parte no afectada por la inconstitucionalidad.', now(), now()),
('864679cd-f413-5f09-b7fe-121f912ab1ff','11111111-1111-1111-1111-111111111220','Artículo 165 — ¿Qué establece?','Una ley orgánica regulará el funcionamiento del Tribunal Constitucional, el estatuto de sus miembros, el procedimiento ante
el mismo y las condiciones para el ejercicio de las acciones.
TÍTULO X
De la reforma constitucional', now(), now()),
('7ab4d73f-f84d-5408-a064-37c2f25c5d14','11111111-1111-1111-1111-111111111221','Artículo 166 — ¿Qué establece?','La iniciativa de reforma constitucional se ejercerá en los términos previstos en los apartados 1 y 2 del artículo 87.', now(), now()),
('29c9d231-e70c-5e04-8337-bdda906f64e7','11111111-1111-1111-1111-111111111221','Artículo 167.1 — ¿Qué establece este apartado?','Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las
Cámaras. Si no hubiera acuerdo entre ambas, se intentará
obtenerlo mediante la creación de una Comisión de composición paritaria de Diputados y Senadores, que presentará
un texto que será votado por el Congreso y el Senado.', now(), now()),
('96d65aac-b062-5a90-bf6e-ba24657ab5e9','11111111-1111-1111-1111-111111111221','Artículo 167.2 — ¿Qué establece este apartado?','De no lograrse la aprobación mediante el procedimiento del
apartado anterior, y siempre que el texto hubiere obtenido
el voto favorable de la mayoría absoluta del Senado, el Congreso, por mayoría de dos tercios, podrá aprobar la reforma.', now(), now()),
('c54f879c-853d-56a5-a922-33ee2e9a1d3f','11111111-1111-1111-1111-111111111221','Artículo 167.3 — ¿Qué establece este apartado?','Aprobada la reforma por las Cortes Generales, será sometida a referéndum para su ratificación cuando así lo soliciten,
dentro de los quince días siguientes a su aprobación, una
décima parte de los miembros de cualquiera de las Cámaras.', now(), now()),
('0753feed-a093-541e-906b-12238be2383b','11111111-1111-1111-1111-111111111221','Artículo 168.1 — ¿Qué establece este apartado?','Cuando se propusiere la revisión total de la Constitución o
una parcial que afecte al Título preliminar, al Capítulo
segundo, Sección primera del Título I, o al Título II, se procederá a la aprobación del principio por mayoría de dos
tercios de cada Cámara, y a la disolución inmediata de las
Cortes.', now(), now()),
('4d1ac115-8b9a-5028-80f3-09b1d1bfbf64','11111111-1111-1111-1111-111111111221','Artículo 168.2 — ¿Qué establece este apartado?','Las Cámaras elegidas deberán ratificar la decisión y proceder al estudio del nuevo texto constitucional, que deberá ser
aprobado por mayoría de dos tercios de ambas Cámaras.', now(), now()),
('dbdd56db-e826-573f-8d2e-c145631cb29d','11111111-1111-1111-1111-111111111221','Artículo 168.3 — ¿Qué establece este apartado?','Aprobada la reforma por las Cortes Generales, será sometida a referéndum para su ratificación.', now(), now()),
('f9abd3a3-79d2-5ded-8951-f90f6f2cd2e8','11111111-1111-1111-1111-111111111221','Artículo 169 — ¿Qué establece?','No podrá iniciarse la reforma constitucional en tiempo de guerra o de vigencia de alguno de los estados previstos en el
artículo 116.', now(), now()),
('720eb1b2-83c4-5f7d-8d82-aab1eee2006e','11111111-1111-1111-1111-111111111202','Disp. Adicional Primera — ¿Qué establece?','La Constitución ampara y respeta los derechos históricos de los
territorios forales.
La actualización general de dicho régimen foral se llevará a
cabo, en su caso, en el marco de la Constitución y de los Estatutos de Autonomía.', now(), now()),
('6d010b7a-e71b-58d9-8f1e-7b2b66b349a1','11111111-1111-1111-1111-111111111202','Disp. Adicional Segunda — ¿Qué establece?','La declaración de mayoría de edad contenida en el artículo 12
de esta Constitución no perjudica las situaciones amparadas por
los derechos forales en el ámbito del Derecho privado.', now(), now()),
('5296d67c-e5a4-5694-be4d-ec86fb900d0a','11111111-1111-1111-1111-111111111202','Disp. Adicional Tercera — ¿Qué establece?','La modificación del régimen económico y fiscal del archipiélago
canario requerirá informe previo de la Comunidad Autónoma o,
en su caso, del órgano provisional autonómico.', now(), now()),
('7f323be9-f95e-5c5e-b8d1-cdc462e611b8','11111111-1111-1111-1111-111111111202','Disp. Adicional Cuarta — ¿Qué establece?','En las Comunidades Autónomas donde tengan su sede más de
una Audiencia Territorial, los Estatutos de Autonomía respectivos podrán mantener las existentes, distribuyendo las competencias entre ellas, siempre de conformidad con lo previsto en
la ley orgánica del poder judicial y dentro de la unidad e independencia de éste.', now(), now()),
('88fdfb89-a728-5ff6-ae33-fe435631f4d3','11111111-1111-1111-1111-111111111202','Disp. Transitoria Primera — ¿Qué establece?','En los territorios dotados de un régimen provisional de autonomía, sus órganos colegiados superiores, mediante acuerdo
adoptado por la mayoría absoluta de sus miembros, podrán sustituir la iniciativa que en el apartado 2 del artículo 143 atribuye
a las Diputaciones Provinciales o a los órganos interinsulares
correspondientes.', now(), now()),
('84043c40-d9d8-5cb5-bbb7-14348afe7f5f','11111111-1111-1111-1111-111111111202','Disp. Transitoria Segunda — ¿Qué establece?','Los territorios que en el pasado hubiesen plebiscitado afirmativamente proyectos de Estatuto de autonomía y cuenten, al
tiempo de promulgarse esta Constitución, con regímenes provisionales de autonomía podrán proceder inmediatamente en la
forma que se prevé en el apartado 2 del artículo 148, cuando así
lo acordaren, por mayoría absoluta, sus órganos preautonómicos colegiados superiores, comunicándolo al Gobierno. El proyecto de Estatuto será elaborado de acuerdo con lo establecido
en el artículo 151, número 2, a convocatoria del órgano colegiado preautonómico.', now(), now()),
('65b8bb0d-149c-5838-9ae4-e418d9a3a178','11111111-1111-1111-1111-111111111202','Disp. Transitoria Tercera — ¿Qué establece?','La iniciativa del proceso autonómico por parte de las Corporaciones locales o de sus miembros, prevista en el apartado 2 del
artículo 143, se entiende diferida, con todos sus efectos, hasta
la celebración de las primeras elecciones locales una vez vigente
la Constitución.', now(), now()),
('07894a20-aa44-5a5d-b99c-4f03f5cf229d','11111111-1111-1111-1111-111111111202','Disp. Transitoria Cuarta — ¿Qué establece?','1. En el caso de Navarra, y a efectos de su incorporación al
Consejo General Vasco o al régimen autonómico vasco que
le sustituya, en lugar de lo que establece el artículo 143 de
la Constitución, la iniciativa corresponde al Órgano Foral
competente, el cual adoptará su decisión por mayoría de los
miembros que lo componen. Para la validez de dicha iniciativa será preciso, además, que la decisión del Órgano Foral
competente sea ratificada por referéndum expresamente
convocado al efecto, y aprobado por mayoría de los votos
válidos emitidos.
2. Si la iniciativa no prosperase, solamente se podrá reproducir
la misma en distinto período del mandato del Órgano Foral
competente, y en todo caso, cuando haya transcurrido el
plazo mínimo que establece el artículo 143.', now(), now()),
('58153d35-55da-529f-9b58-c00558d462d2','11111111-1111-1111-1111-111111111202','Disp. Transitoria Quinta — ¿Qué establece?','Las ciudades de Ceuta y Melilla podrán constituirse en Comunidades Autónomas si así lo deciden sus respectivos Ayuntamientos, mediante acuerdo adoptado por la mayoría absoluta de sus
miembros y así lo autorizan las Cortes Generales, mediante una
ley orgánica, en los términos previstos en el artículo 144.', now(), now()),
('57419600-ea1b-5f72-83aa-c1b7466b1f25','11111111-1111-1111-1111-111111111202','Disp. Transitoria Sexta — ¿Qué establece?','Cuando se remitieran a la Comisión Constitucional del Congreso
varios proyectos de Estatuto, se dictaminarán por el orden de
entrada en aquélla, y el plazo de dos meses a que se refiere el
artículo 151 empezará a contar desde que la Comisión termine
el estudio del proyecto o proyectos de que sucesivamente haya
conocido.', now(), now()),
('4a449a5d-1a8a-5e58-bc44-8e4aa5401a01','11111111-1111-1111-1111-111111111202','Disp. Transitoria Séptima — ¿Qué establece?','Los organismos provisionales autonómicos se considerarán
disueltos en los siguientes casos:
a) Una vez constituidos los órganos que establezcan los
Estatutos de Autonomía aprobados conforme a esta
Constitución.
b) En el supuesto de que la iniciativa del proceso autonómico no llegara a prosperar por no cumplir los requisitos previstos en el artículo 143.
c) Si el organismo no hubiera ejercido el derecho que le
reconoce la disposición transitoria primera en el plazo
de tres años.', now(), now()),
('5c3d40f7-5f2f-5b0f-8424-96565b816e60','11111111-1111-1111-1111-111111111202','Disp. Transitoria Octava — ¿Qué establece?','1. Las Cámaras que han aprobado la presente Constitución
asumirán, tras la entrada en vigor de la misma, las funciones
y competencias que en ella se señalan, respectivamente,
para el Congreso y el Senado, sin que en ningún caso su
mandato se extienda más allá del 15 de junio de 1981.
2. A los efectos de lo establecido en el artículo 99, la promulgación de la Constitución se considerará como supuesto
constitucional en el que procede su aplicación. A tal efecto,
a partir de la citada promulgación se abrirá un período de
treinta días para la aplicación de lo dispuesto en dicho
artículo.
Durante este período, el actual Presidente del Gobierno,
que asumirá las funciones y competencias que para dicho
cargo establece la Constitución, podrá optar por utilizar la
facultad que le reconoce el artículo 115 o dar paso, mediante
la dimisión, a la aplicación de lo establecido en el artículo
99, quedando en este último caso en la situación prevista en
el apartado 2 del artículo 101.
3. En caso de disolución, de acuerdo con lo previsto en el
artículo 115, y si no se hubiera desarrollado legalmente lo
previsto en los artículos 68 y 69, serán de aplicación en las
elecciones las normas vigentes con anterioridad, con las
solas excepciones de que en lo referente a inelegibilidades
e incompatibilidades se aplicará directamente lo previsto
en el inciso segundo de la letra b) del apartado 1 del artículo 70 de la Constitución, así como lo dispuesto en la
misma respecto a la edad para el voto y lo establecido en
el artículo 69,3.', now(), now()),
('e7acaf3f-4aaf-59fd-81cc-616bd95be772','11111111-1111-1111-1111-111111111202','Disp. Transitoria Novena — ¿Qué establece?','A los tres años de la elección por vez primera de los miembros
del Tribunal Constitucional se procederá por sorteo para la
designación de un grupo de cuatro miembros de la misma procedencia electiva que haya de cesar y renovarse. A estos solos
efectos se entenderán agrupados como miembros de la misma
procedencia a los dos designados a propuesta del Gobierno y a
los dos que proceden de la formulada por el Consejo General
del Poder Judicial. Del mismo modo se procederá transcurridos
otros tres años entre los dos grupos no afectados por el sorteo
anterior. A partir de entonces se estará a lo establecido en el
número 3 del artículo 159.', now(), now()),
('f32cf2e3-b282-5cda-8c3e-0e24b38ba62b','11111111-1111-1111-1111-111111111202','Disp. Derogatoria 1 — ¿Qué establece?','Queda derogada la Ley 1/1977, de 4 de enero, para la
Reforma Política, así como, en tanto en cuanto no estuvieran
ya derogadas por la anteriormente mencionada Ley, la de
Principios del Movimiento Nacional, de 17 de mayo de
1958; el Fuero de los Españoles, de 17 de julio de 1945; el
del Trabajo, de 9 de marzo de 1938; la Ley Constitutiva de
las Cortes, de 17 de julio de 1942; la Ley de Sucesión en la
Jefatura del Estado, de 26 de julio de 1947, todas ellas
modificadas por la Ley Orgánica del Estado, de 10 de enero
de 1967, y en los mismos términos esta última y la de Referéndum Nacional de 22 de octubre de 1945.', now(), now()),
('803dde02-dd64-5dfb-9fd3-f2048b4dea4d','11111111-1111-1111-1111-111111111202','Disp. Derogatoria 2 — ¿Qué establece?','En tanto en cuanto pudiera conservar alguna vigencia, se
considera definitivamente derogada la Ley de 25 de octubre
de 1839 en lo que pudiera afectar a las provincias de Álava,
Guipúzcoa y Vizcaya.
En los mismos términos se considera definitivamente derogada la Ley de 21 de julio de 1876.', now(), now()),
('ba1c5336-fbdb-5380-8530-82c468795063','11111111-1111-1111-1111-111111111202','Disp. Derogatoria 3 — ¿Qué establece?','Asimismo quedan derogadas cuantas disposiciones se
opongan a lo establecido en esta Constitución.', now(), now()),
('dc542c4b-4ebd-54ba-bb53-0098d24364e2','11111111-1111-1111-1111-111111111202','Disp. Final  — ¿Qué establece?','Esta Constitución entrará en vigor el mismo día de la publicación
de su texto oficial en el boletín oficial del Estado. Se publicará también en las demás lenguas de España.
Por tanto, Mando a todos los españoles, particulares y autoridades, que guarden y hagan guardar esta Constitución como norma fundamental del Estado. Palacio de las Cortes, a veintisiete de diciembre de mil novecientos setenta y ocho.
JUAN CARLOS
El pResidente de las coRtes
ANTONIO HERNÁNDEZ GIL
El pResidente del congReso de los diputados
FERNANDO ÁLVAREZ DE MIRANDA Y TORRES
El pResidente del senado
antonio fontán pÉReZ', now(), now())
    ON CONFLICT (id) DO UPDATE SET
    unit_id = EXCLUDED.unit_id,
                            front = EXCLUDED.front,
                            back = EXCLUDED.back,
                            updated_at = now();